begin;

-- Idempotent core case/answer-key seed. Never set DA_DUYET.
insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-ho-hap-005',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-ho-hap-005","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Sốt kéo dài, ho khạc đờm mủ thối ở người nghiện rượu","setting":"giuong","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":55,"sex":"nam","patient_label":"Ông T. N. D. (mô phỏng)"},"presentation":{"intro":"Ông nhập khoa Nội vì sốt kéo dài hai tuần, ho khạc nhiều đờm mủ có mùi hôi và sụt cân.","place":null,"clock":null,"night":false},"vitals":{"hr":98,"sbp":118,"dbp":70,"rr":22,"temperature_c":38.6,"spo2":94},"history":[{"question":"Sốt và ho kéo dài bao lâu, tính chất đờm ra sao?","response":"Hai tuần nay sốt cao về chiều, ho khạc ra khoảng nửa chén đờm mủ vàng xanh, có mùi hôi."},{"question":"Có ho ra máu, đau ngực không?","response":"Ho ra ít đờm lẫn tia máu hai lần; đau ngực phải nhẹ khi ho."},{"question":"Có sụt cân, ra mồ hôi đêm, ăn kém không?","response":"Sụt 4 kg trong hai tuần, ăn kém, mệt, mồ hôi đêm."},{"question":"Có từng hôn mê, co giật, sặc, nuốt khó, say rượu gần đây không?","response":"Uống rượu nhiều mỗi ngày, hôm trước nhập tiệc say bí tỉ, nằm li bì ngoài hiên; thỉnh thoảng sặc."},{"question":"Sức khỏe răng miệng?","response":"Răng sâu nhiều, viêm nướu, mùi hôi miệng."},{"question":"Tiền sử lao, tiếp xúc người ho kéo dài, HIV, đái tháo đường?","response":"Chưa tiền sử lao; không tiếp xúc nguồn lao; chưa xét nghiệm HIV; không biết bệnh đái tháo đường."},{"question":"Hút thuốc?","response":"Hút 25 gói-năm."},{"question":"Có dị ứng thuốc, penicillin?","response":"Chưa ghi nhận."}],"examination":[{"group":"K","item":"Phổi","finding":"Hội chứng đông đặc vùng đáy phổi phải phía sau, có tiếng thổi hang nhỏ, ran nổ và ran ẩm to hạt."},{"group":"K","item":"Miệng, răng","finding":"Vệ sinh răng miệng rất kém, nhiều răng sâu, viêm nướu mủ, hơi thở hôi."},{"group":"K","item":"Dấu hiệu ngón tay, dinh dưỡng","finding":"Ngón tay dùi trống nhẹ, gầy, BMI 18,5 kg/m2."},{"group":"K","item":"Tim, bụng, thần kinh","finding":"Tim nhanh đều; gan to 2 cm; thần kinh không dấu khu trú."}],"investigations":[{"name":"X-quang ngực thẳng nghiêng","duration_minutes":10,"result":"Hang tròn 5 cm có mực nước hơi ở thùy dưới phải (phân thùy sau), thành dày."},{"name":"CT ngực cản quang","duration_minutes":40,"result":"Ổ áp xe 5,2 cm, thành dày bắt thuốc, mực nước hơi, không tắc nghẽn phế quản; không u; tràn dịch màng phổi nhỏ cùng bên."},{"name":"Công thức máu, CRP, glucose, albumin, chức năng gan","duration_minutes":10,"result":"Bạch cầu 18,4 G/L, đa nhân 86%; Hb 106 g/L; CRP 210 mg/L; glucose 7,2 mmol/L; albumin 28 g/L; AST 78, ALT 52 U/L, GGT tăng."},{"name":"Soi, cấy đờm (vi khuẩn, nấm), cấy máu, tìm AFB 3 mẫu hoặc Xpert MTB/RIF","duration_minutes":10,"result":"Cấy đờm: vi khuẩn hỗn hợp có kỵ khí; Xpert âm tính; AFB âm tính 3 mẫu."},{"name":"HIV, HbA1c","duration_minutes":10,"result":"HIV âm tính; HbA1c 5,9%."},{"name":"Chọc hút dẫn lưu xuyên thành ngực ngay mọi ổ áp xe phổi","duration_minutes":10,"result":"Không là bước đầu thường quy, chỉ khi thất bại nội khoa hoặc ổ lớn trên 6 cm không dẫn lưu được."}],"choices":{"diagnosis":{"ydx":["Áp xe phổi nguyên phát do hít, thùy dưới phải","Viêm phổi cộng đồng đơn thuần do phế cầu","Lao phổi hang","Ung thư phổi hoại tử trung tâm"]},"actions":["Dùng thuốc ức chế ho mạnh","Kháng sinh tĩnh mạch phủ kỵ khí (ampicillin–sulbactam hoặc amoxicillin–clavulanat)","Nhập viện, lấy cấy đờm, cấy máu trước kháng sinh, đường truyền và bù dịch","Chọc hút xuyên thành ngực ngay lập tức","Chụp CT ngực, xét nghiệm lao (Xpert, AFB) và nội soi phế quản nếu không đáp ứng","Cho điều trị lao theo kinh nghiệm không cần xét nghiệm","Dẫn lưu tư thế, dinh dưỡng, thiamin, bỏ rượu và chăm sóc răng miệng"]}}'::jsonb,
  '3772e20af7bd7c391c66dddf850c868dcbae67edc01c242e1ce85c3ddcdc21af'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-ho-hap-005',
  '{"schema_version":"1.0.0","case_id":"noi-ho-hap-005","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-ho-hap-005-1","resource_type":"textbook","source":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Áp xe phổi.","title":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Áp xe phổi.","organization":null,"year_version":null,"citation":"Giáo trình Nội khoa, Bộ môn Nội, Trường Đại học Y Hà Nội, phần Áp xe phổi.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-ho-hap-005-2","resource_type":"other","source":"Hướng dẫn chẩn đoán và điều trị các bệnh hô hấp thường gặp, Bộ Y tế Việt Nam, bản cập nhật.","title":"Hướng dẫn chẩn đoán và điều trị các bệnh hô hấp thường gặp, Bộ Y tế Việt Nam, bản cập nhật.","organization":null,"year_version":null,"citation":"Hướng dẫn chẩn đoán và điều trị các bệnh hô hấp thường gặp, Bộ Y tế Việt Nam, bản cập nhật.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-ho-hap-005-3","resource_type":"textbook","source":"Mandell, Douglas and Bennett Principles and Practice of Infectious Diseases, phần Lung Abscess.","title":"Mandell, Douglas and Bennett Principles and Practice of Infectious Diseases, phần Lung Abscess.","organization":null,"year_version":null,"citation":"Mandell, Douglas and Bennett Principles and Practice of Infectious Diseases, phần Lung Abscess.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"essential"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Lao phổi hang","credit":"none"},{"text":"Ung thư phổi hoại tử trung tâm","credit":"none"},{"text":"Áp xe phổi nguyên phát do hít, thùy dưới phải","credit":"full"},{"text":"Viêm phổi cộng đồng đơn thuần do phế cầu","credit":"none"}]},"action_options":[{"text":"Nhập viện, lấy cấy đờm, cấy máu trước kháng sinh, đường truyền và bù dịch","time_minutes":2,"grade":"critical","rationale":"Xác định vi khuẩn và hỗ trợ toàn trạng, thiếu dinh dưỡng."},{"text":"Kháng sinh tĩnh mạch phủ kỵ khí (ampicillin–sulbactam hoặc amoxicillin–clavulanat)","time_minutes":2,"grade":"critical","rationale":"Áp xe phổi thường do vi khuẩn kỵ khí miệng; điều trị kháng sinh kéo dài là nền tảng."},{"text":"Chụp CT ngực, xét nghiệm lao (Xpert, AFB) và nội soi phế quản nếu không đáp ứng","time_minutes":2,"grade":"recommended","rationale":"Loại trừ lao, ung thư, dị vật tắc phế quản."},{"text":"Dẫn lưu tư thế, dinh dưỡng, thiamin, bỏ rượu và chăm sóc răng miệng","time_minutes":2,"grade":"recommended","rationale":"Giảm yếu tố nguy cơ, cải thiện sự hồi phục."},{"text":"Dùng thuốc ức chế ho mạnh","time_minutes":1,"grade":"waste","rationale":"Cản trở khạc đờm, ứ mủ trong hang."},{"text":"Cho điều trị lao theo kinh nghiệm không cần xét nghiệm","time_minutes":0,"grade":"harmful","rationale":"Không có bằng chứng lao; chậm điều trị nguyên nhân thực sự."},{"text":"Chọc hút xuyên thành ngực ngay lập tức","time_minutes":0,"grade":"harmful","rationale":"Không là đầu tay, nguy cơ tràn mủ màng phổi và tràn khí."}],"teaching_explanation":"Áp xe phổi hay gặp sau hít ở người say rượu, răng miệng kém; hang có mực nước hơi, đờm thối. Điều trị cốt lõi là kháng sinh kéo dài phủ kỵ khí, dẫn lưu tư thế và loại trừ lao, ung thư."}'::jsonb,
  '869813dcd5f71cf09b58e7f93c9317a31042fa96161e45aa92171e0d5468007d'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-noi-tiet-001',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-noi-tiet-001","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Sụt cân, hồi hộp, sốt cao và kích động","setting":"giuong","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":34,"sex":"nữ","patient_label":"Người bệnh mô phỏng N11"},"presentation":{"intro":"Người bệnh nữ 34 tuổi, đã biết bướu giáp lan tỏa nhưng tự ngưng thuốc, nhập cấp cứu vì sốt cao, tim nhanh, kích động sau một đợt viêm họng.","place":null,"clock":null,"night":false},"vitals":{"hr":156,"sbp":148,"dbp":68,"rr":28,"temperature_c":39.6,"spo2":95},"history":[{"question":"Các triệu chứng hiện tại bắt đầu thế nào?","response":"Ba ngày nay sốt cao, hồi hộp đánh trống ngực liên tục, nôn và tiêu chảy; hôm nay nói lảm nhảm, ngủ không được."},{"question":"Có tiền sử bệnh tuyến giáp và dùng thuốc gì không?","response":"Được chẩn đoán cường giáp 8 tháng trước, uống thiamazol; tự ngưng khoảng 6 tuần nay vì thấy đỡ và đắt tiền."},{"question":"Có yếu tố khởi phát như nhiễm trùng, phẫu thuật, chuyển dạ, dùng iod không?","response":"Viêm họng đau rát một tuần, chưa dùng kháng sinh; không phẫu thuật, không chụp có cản quang, không mang thai (thử âm tính)."},{"question":"Sụt cân, run tay, sợ nóng, ra mồ hôi nhiều không?","response":"Sụt 9 kg trong 5 tháng dù ăn nhiều, run tay, sợ nóng, mồ hôi nhiều, kinh thưa."},{"question":"Có khó thở, phù, đau ngực hoặc bệnh tim trước đây không?","response":"Mệt khó thở khi gắng sức vài tuần nay, hai chân phù nhẹ; không đau ngực, chưa biết bệnh tim."},{"question":"Có tiền sử hen phế quản hoặc dị ứng thuốc không?","response":"Không hen, không dị ứng thuốc."},{"question":"Gia đình có ai mắc bệnh tuyến giáp không?","response":"Mẹ có bướu cổ."}],"examination":[{"group":"K","item":"Toàn thân và tri giác","finding":"Kích động, lẫn lộn từng lúc, da nóng ẩm, vã mồ hôi, run mịn hai tay."},{"group":"K","item":"Tuyến giáp và mắt","finding":"Bướu giáp lan tỏa độ II, mật độ chắc, có tiếng thổi tâm thu; lồi mắt hai bên nhẹ, co kéo mi trên."},{"group":"K","item":"Tim mạch","finding":"Nhịp tim nhanh không đều, rung nhĩ đáp ứng thất nhanh, huyết áp tâm thu cao, hiệu áp rộng."},{"group":"K","item":"Phổi và bụng","finding":"Ran ẩm hai đáy phổi; bụng mềm, không đề kháng, nhu động ruột tăng."},{"group":"K","item":"Thần kinh cơ","finding":"Phản xạ gân xương tăng, yếu cơ gốc chi nhẹ, không dấu thần kinh khu trú."}],"investigations":[{"name":"TSH, FT4, FT3","duration_minutes":10,"result":"TSH dưới 0,01 mIU/L; FT4 71 pmol/L (bình thường 12 đến 22); FT3 vượt ngưỡng đo."},{"name":"Điện tâm đồ","duration_minutes":10,"result":"Rung nhĩ đáp ứng thất nhanh khoảng 150 lần/phút, không có ST chênh."},{"name":"Công thức máu, CRP, đường huyết, điện giải, chức năng gan thận","duration_minutes":10,"result":"Bạch cầu 14,5 G/L, CRP 62 mg/L; glucose 8,6 mmol/L; kali 3,3 mmol/L; AST, ALT tăng nhẹ; creatinin bình thường."},{"name":"Test nhanh liên cầu hoặc cấy họng","duration_minutes":10,"result":"Test nhanh liên cầu nhóm A dương tính."},{"name":"X quang ngực","duration_minutes":10,"result":"Bóng tim hơi to, ứ huyết nhẹ hai rốn phổi."},{"name":"Xạ hình tuyến giáp ngay lập tức, trước khi kiểm soát nhịp tim","duration_minutes":10,"result":"Không cần thiết trong cấp cứu, làm chậm điều trị."}],"choices":{"diagnosis":{"ydx":["Viêm tuyến giáp bán cấp có cường giáp thoáng qua","U tủy thượng thận cơn kịch phát","Nhiễm khuẩn huyết đơn thuần kèm rối loạn lo âu","Cơn bão giáp trên nền bệnh Basedow ngưng thuốc, khởi phát do nhiễm liên cầu"]},"actions":["Cho dung dịch iod sau khi đã dùng kháng giáp ít nhất 1 giờ","Truyền dung dịch ưu trương mạnh, tiêm aspirin hạ sốt và chờ kết quả xạ hình","Dùng thiamazol hoặc propylthiouracil liều tấn công","Kháng sinh phù hợp điều trị viêm họng do liên cầu và bù dịch, bù kali","Đánh giá ABC, theo dõi monitor, hạ nhiệt bằng paracetamol và làm mát tích cực","Hydrocortisone tĩnh mạch"]}}'::jsonb,
  '9797ed50e03aca13124be0fe0087a3b4c81893c90728bc2b7b965d45e637ed9d'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-noi-tiet-001',
  '{"schema_version":"1.0.0","case_id":"noi-noi-tiet-001","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-thyroid-ata-2016","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/27521067/","title":"Ross DS, et al. 2016 American Thyroid Association Guidelines for Diagnosis and Management of Hyperthyroidism and Other Causes of Thyrotoxicosis. Thyroid 2016.","organization":null,"year_version":null,"citation":"Ross DS, et al. 2016 American Thyroid Association Guidelines for Diagnosis and Management of Hyperthyroidism and Other Causes of Thyrotoxicosis. Thyroid 2016.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-thyroid-storm-jts-2016","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/27746415/","title":"Satoh T, et al. 2016 Guidelines for the management of thyroid storm from the Japan Thyroid Association and Japan Endocrine Society. Endocr J 2016.","organization":null,"year_version":null,"citation":"Satoh T, et al. 2016 Guidelines for the management of thyroid storm from the Japan Thyroid Association and Japan Endocrine Society. Endocr J 2016.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-noi-tiet-001-3","resource_type":"textbook","source":"Giáo trình Nội khoa, bộ môn Nội, các trường đại học Y Việt Nam.","title":"Giáo trình Nội khoa, bộ môn Nội, các trường đại học Y Việt Nam.","organization":null,"year_version":null,"citation":"Giáo trình Nội khoa, bộ môn Nội, các trường đại học Y Việt Nam.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm tuyến giáp bán cấp có cường giáp thoáng qua","credit":"none"},{"text":"Cơn bão giáp trên nền bệnh Basedow ngưng thuốc, khởi phát do nhiễm liên cầu","credit":"full"},{"text":"Nhiễm khuẩn huyết đơn thuần kèm rối loạn lo âu","credit":"none"},{"text":"U tủy thượng thận cơn kịch phát","credit":"none"}]},"action_options":[{"text":"Đánh giá ABC, theo dõi monitor, hạ nhiệt bằng paracetamol và làm mát tích cực","time_minutes":2,"grade":"critical","rationale":"Sốt cao làm tăng chuyển hóa; tránh aspirin vì đẩy hormon tự do ra khỏi protein gắn."},{"text":"Dùng thiamazol hoặc propylthiouracil liều tấn công","time_minutes":2,"grade":"critical","rationale":"Ức chế tổng hợp hormon giáp là nền tảng của điều trị."},{"text":"Cho dung dịch iod sau khi đã dùng kháng giáp ít nhất 1 giờ","time_minutes":2,"grade":"recommended","rationale":"Iod ức chế giải phóng hormon, nhưng dùng trước kháng giáp sẽ cung cấp nguyên liệu tổng hợp."},{"text":"Hydrocortisone tĩnh mạch","time_minutes":2,"grade":"recommended","rationale":"Giảm chuyển T4 thành T3, điều trị suy thượng thận tương đối và bệnh nền tự miễn."},{"text":"Kháng sinh phù hợp điều trị viêm họng do liên cầu và bù dịch, bù kali","time_minutes":2,"grade":"recommended","rationale":"Điều trị yếu tố khởi phát và rối loạn điện giải."},{"text":"Truyền dung dịch ưu trương mạnh, tiêm aspirin hạ sốt và chờ kết quả xạ hình","time_minutes":0,"grade":"harmful","rationale":"Làm nặng thêm tình trạng và trì hoãn điều trị cứu mạng."}],"teaching_explanation":"Cơn bão giáp là chẩn đoán lâm sàng dựa trên cường giáp nặng kèm rối loạn đa cơ quan (sốt, tim mạch, thần kinh, tiêu hóa), thường có yếu tố khởi phát. Điều trị khẩn theo thứ tự: kiểm soát triệu chứng, ức chế tổng hợp rồi giải phóng hormon, giảm chuyển T4 thành T3, điều trị yếu tố khởi phát."}'::jsonb,
  'd600eb3231f1eb45d441a7f054af65b9501ede27cb165f8ede761342c74db6e0'
