insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-noi-tiet-002',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-noi-tiet-002","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Khát nhiều, tiểu nhiều và giảm thị lực, tê bàn chân","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":52,"sex":"nam","patient_label":"Người bệnh mô phỏng N12"},"presentation":{"intro":"Người bệnh nam 52 tuổi đến phòng khám nội tiết vì khát nhiều, tiểu nhiều, mờ mắt và tê bàn chân hơn 6 tháng, chưa từng khám tầm soát đường huyết.","place":null,"clock":null,"night":false},"vitals":{"hr":84,"sbp":152,"dbp":94,"rr":18,"temperature_c":36.8,"spo2":98},"history":[{"question":"Các triệu chứng bắt đầu từ khi nào và diễn tiến ra sao?","response":"Khát nước, uống nhiều, tiểu nhiều cả ban đêm khoảng 6 tháng; sụt 5 kg; mờ mắt tăng dần; tê rần hai bàn chân."},{"question":"Có tiền sử đái tháo đường, tăng huyết áp, rối loạn mỡ máu không?","response":"Chưa từng đo đường huyết. Biết huyết áp cao 2 năm nhưng uống thuốc không đều. Chưa kiểm tra mỡ máu."},{"question":"Gia đình có ai bị đái tháo đường không?","response":"Cha và anh trai bị đái tháo đường."},{"question":"Chế độ ăn, vận động, hút thuốc, uống rượu?","response":"Ăn nhiều tinh bột và nước ngọt, ít vận động, hút 20 gói-năm, uống rượu cuối tuần."},{"question":"Có đau ngực, khó thở khi gắng sức, đau cách hồi không?","response":"Không đau ngực; đi bộ xa thấy mỏi bắp chân nhưng nghỉ thì đỡ ít."},{"question":"Có nhiễm trùng da, nấm âm hộ-quy đầu, vết loét lâu lành không?","response":"Có ngứa vùng bẹn, vết xước ở chân lâu lành."},{"question":"Có nôn, đau bụng, thở sâu, lơ mơ không?","response":"Không có."}],"examination":[{"group":"K","item":"Chỉ số nhân trắc","finding":"BMI 29,4 kg/m2, vòng eo 98 cm, có béo bụng."},{"group":"K","item":"Khám mắt sơ bộ","finding":"Thị lực giảm nhẹ hai mắt; soi đáy mắt thấy vi phình mạch và xuất huyết dạng chấm."},{"group":"K","item":"Khám bàn chân","finding":"Giảm cảm giác monofilament ở ngón và gan chân hai bên, mất phản xạ gót; mạch mu chân yếu; da khô, không loét."},{"group":"K","item":"Tim phổi và bụng","finding":"Tim đều, không tiếng thổi; phổi trong; gan không to."}],"investigations":[{"name":"Đường huyết tĩnh mạch lúc đói và HbA1c","duration_minutes":10,"result":"Glucose đói 13,2 mmol/L; HbA1c 10,8%."},{"name":"Creatinin, eGFR và tỷ số albumin/creatinin niệu (UACR)","duration_minutes":10,"result":"Creatinin 98 umol/L, eGFR 82 mL/phút/1,73 m2; UACR 120 mg/g (microalbumin niệu)."},{"name":"Bộ mỡ máu","duration_minutes":10,"result":"LDL-C 4,1 mmol/L; triglycerid 3,6 mmol/L; HDL-C 0,9 mmol/L."},{"name":"Tổng phân tích nước tiểu","duration_minutes":10,"result":"Glucose niệu 3+, ceton âm tính, protein vết."},{"name":"Điện tâm đồ","duration_minutes":10,"result":"Nhịp xoang, không thay đổi thiếu máu cục bộ."},{"name":"Nghiệm pháp dung nạp glucose đường uống để xác nhận khi glucose đã vượt ngưỡng rõ rệt","duration_minutes":10,"result":"Không cần thiết khi triệu chứng điển hình và glucose đói đã vượt 7,0 mmol/L."}],"choices":{"diagnosis":{"ydx":["Đái tháo đường típ 1 khởi phát muộn","Rối loạn dung nạp glucose đơn thuần","Đái tháo đường típ 2 mới chẩn đoán, đã có biến chứng võng mạc, thần kinh và bệnh thận giai đoạn sớm","Đái tháo đường thai kỳ"]},"actions":["Chuyển nhãn khoa và hướng dẫn chăm sóc bàn chân, ngừng thuốc lá","Xác nhận chẩn đoán đái tháo đường bằng glucose đói và HbA1c","Bắt đầu metformin theo eGFR, tăng liều dần, kèm chế độ ăn và vận động","Chỉ khuyên ăn kiêng, cho về và hẹn tái khám sau một năm","Cân nhắc phối hợp thuốc thứ hai hoặc insulin nền vì HbA1c rất cao","Dùng ức chế men chuyển hoặc chẹn thụ thể; thêm statin cường độ trung bình đến cao"]}}'::jsonb,
  'ad86547a24947145807e139f33738d03b600092a8f8e61d383c376196a8c5236'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
