values (
  'noi-noi-tiet-002',
  '{"schema_version":"1.0.0","case_id":"noi-noi-tiet-002","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-noi-tiet-002-1","resource_type":"other","source":"American Diabetes Association. Standards of Care in Diabetes 2024. Diabetes Care 2024;47(Suppl 1).","title":"American Diabetes Association. Standards of Care in Diabetes 2024. Diabetes Care 2024;47(Suppl 1).","organization":null,"year_version":null,"citation":"American Diabetes Association. Standards of Care in Diabetes 2024. Diabetes Care 2024;47(Suppl 1).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-5481-2020","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-5481-qd-byt-huong-dan-chan-doan-va-dieu-tri-dai-thao-duong-tip-2-196326-d1.html","title":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị đái tháo đường típ 2 (Quyết định 5481/QĐ-BYT, 2020).","organization":null,"year_version":null,"citation":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị đái tháo đường típ 2 (Quyết định 5481/QĐ-BYT, 2020).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-noi-tiet-002-3","resource_type":"other","source":"KDIGO 2022 Clinical Practice Guideline for Diabetes Management in CKD.","title":"KDIGO 2022 Clinical Practice Guideline for Diabetes Management in CKD.","organization":null,"year_version":null,"citation":"KDIGO 2022 Clinical Practice Guideline for Diabetes Management in CKD.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-noi-tiet-002-4","resource_type":"textbook","source":"Giáo trình Nội khoa, bộ môn Nội, các trường đại học Y Việt Nam.","title":"Giáo trình Nội khoa, bộ môn Nội, các trường đại học Y Việt Nam.","organization":null,"year_version":null,"citation":"Giáo trình Nội khoa, bộ môn Nội, các trường đại học Y Việt Nam.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Đái tháo đường típ 1 khởi phát muộn","credit":"none"},{"text":"Đái tháo đường thai kỳ","credit":"none"},{"text":"Rối loạn dung nạp glucose đơn thuần","credit":"none"},{"text":"Đái tháo đường típ 2 mới chẩn đoán, đã có biến chứng võng mạc, thần kinh và bệnh thận giai đoạn sớm","credit":"full"}]},"action_options":[{"text":"Xác nhận chẩn đoán đái tháo đường bằng glucose đói và HbA1c","time_minutes":2,"grade":"critical","rationale":"Triệu chứng cổ điển kèm glucose và HbA1c vượt ngưỡng đủ chẩn đoán."},{"text":"Bắt đầu metformin theo eGFR, tăng liều dần, kèm chế độ ăn và vận động","time_minutes":2,"grade":"critical","rationale":"Metformin là lựa chọn đầu tay khi chức năng thận cho phép."},{"text":"Cân nhắc phối hợp thuốc thứ hai hoặc insulin nền vì HbA1c rất cao","time_minutes":2,"grade":"recommended","rationale":"HbA1c trên 10% thường cần phối hợp sớm để đạt mục tiêu."},{"text":"Dùng ức chế men chuyển hoặc chẹn thụ thể; thêm statin cường độ trung bình đến cao","time_minutes":2,"grade":"recommended","rationale":"Có tăng huyết áp, albumin niệu và nguy cơ tim mạch cao."},{"text":"Chuyển nhãn khoa và hướng dẫn chăm sóc bàn chân, ngừng thuốc lá","time_minutes":2,"grade":"recommended","rationale":"Có tổn thương võng mạc, bệnh thần kinh ngoại biên và mạch máu ngoại vi."},{"text":"Chỉ khuyên ăn kiêng, cho về và hẹn tái khám sau một năm","time_minutes":0,"grade":"harmful","rationale":"Bỏ sót điều trị biến chứng và hạ đường huyết kéo dài."}],"teaching_explanation":"Chẩn đoán đái tháo đường dựa trên tiêu chuẩn glucose và HbA1c; khi mới phát hiện cần tầm soát biến chứng ngay vì bệnh có thể đã tiến triển nhiều năm. Điều trị là gói toàn diện: đường huyết, huyết áp, mỡ máu, ngừng thuốc lá và chăm sóc bàn chân, mắt, thận."}'::jsonb,
  '727e38a944c567a890b4aed80c529a5fc2787dfcc13859d20128946fecd8346d'
)
