insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-than-001',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-than-001","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Tiểu ít sau tiêu chảy ở người dùng thuốc giảm đau và thuốc huyết áp","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":67,"sex":"nam","patient_label":"Người bệnh mô phỏng N13"},"presentation":{"intro":"Người bệnh nam 67 tuổi nhập khoa Nội vì mệt, khát, tiểu rất ít hai ngày sau đợt tiêu chảy và nôn.","place":null,"clock":null,"night":false},"vitals":{"hr":108,"sbp":92,"dbp":58,"rr":20,"temperature_c":37.2,"spo2":97},"history":[{"question":"Tiêu chảy, nôn và ăn uống thời gian qua thế nào?","response":"Tiêu chảy nước 6 đến 8 lần/ngày và nôn trong 3 ngày, uống ít nước, ăn kém."},{"question":"Lượng nước tiểu và màu nước tiểu thế nào?","response":"Từ hôm qua đi tiểu rất ít, nước tiểu vàng sẫm, không đau khi tiểu, không tiểu máu."},{"question":"Đang dùng thuốc gì, đặc biệt thuốc giảm đau, huyết áp, lợi tiểu?","response":"Tăng huyết áp: enalapril và furosemid; đau gối dùng ibuprofen mỗi ngày hơn 2 tuần."},{"question":"Có tiền sử bệnh thận, sỏi tiết niệu, phì đại tiền liệt tuyến không?","response":"Chưa từng bệnh thận; không sỏi; thỉnh thoảng đi tiểu đêm 1 lần."},{"question":"Có dùng thuốc cản quang, kháng sinh nhóm aminoglycosid, thuốc nam không rõ nguồn gốc không?","response":"Không dùng."},{"question":"Có phù, khó thở, đau ngực không?","response":"Không phù, không khó thở, chỉ chóng mặt khi đứng dậy."},{"question":"Có sốt, phát ban, đau khớp mới xuất hiện không?","response":"Không."}],"examination":[{"group":"K","item":"Tình trạng thể tích","finding":"Khô niêm mạc, nếp véo da mất chậm, tĩnh mạch cổ xẹp, mạch nhanh, tụt huyết áp tư thế."},{"group":"K","item":"Tim phổi","finding":"Tim nhanh đều, không tiếng thổi; phổi trong, không ran."},{"group":"K","item":"Bụng và cầu bàng quang","finding":"Bụng mềm, không cầu bàng quang, không điểm đau niệu quản."},{"group":"K","item":"Phù và da","finding":"Không phù; da khô, không ban."}],"investigations":[{"name":"Creatinin, ure, điện giải đồ, khí máu","duration_minutes":10,"result":"Creatinin 238 umol/L (nền khoảng 90 trước đây); ure 21 mmol/L; K 5,3 mmol/L; Na 133 mmol/L; HCO3 17 mmol/L."},{"name":"Tổng phân tích nước tiểu và điện giải niệu","duration_minutes":10,"result":"Tỷ trọng 1,028; protein vết; không hồng cầu, không trụ hạt; Na niệu 12 mmol/L; FeNa 0,6%."},{"name":"Siêu âm thận và đường tiết niệu","duration_minutes":15,"result":"Hai thận kích thước bình thường, đậm độ vỏ bình thường, không ứ nước, bàng quang xẹp."},{"name":"Công thức máu và CRP","duration_minutes":10,"result":"Hematocrit 49%, bạch cầu 10,2 G/L, CRP 8 mg/L."},{"name":"Điện tâm đồ","duration_minutes":10,"result":"Nhịp nhanh xoang, sóng T cao nhọn nhẹ."},{"name":"Sinh thiết thận ngay để xác định nguyên nhân","duration_minutes":10,"result":"Không có chỉ định khi nghĩ nhiều nguyên nhân trước thận hồi phục được."}],"choices":{"diagnosis":{"ydx":["Tổn thương thận cấp trước thận do giảm thể tích, có yếu tố thuốc làm nặng","Viêm cầu thận tiến triển nhanh","Tổn thương thận cấp sau thận do tắc nghẽn tiết niệu","Hoại tử ống thận cấp do thiếu máu kéo dài"]},"actions":["Dùng kháng sinh khi có bằng chứng nhiễm khuẩn, hiệu chỉnh liều theo eGFR","Đánh giá thể tích, bắt đầu bù dịch tinh thể đường tĩnh mạch và theo dõi nước tiểu từng giờ","Làm điện tâm đồ, theo dõi kali, điều chỉnh rối loạn điện giải và toan chuyển hóa","Truyền furosemid liều cao và tiếp tục ibuprofen để giảm đau gối","Siêu âm tiết niệu và tính FeNa để phân biệt trước thận với tại thận","Ngừng tạm thời NSAID, ức chế men chuyển và lợi tiểu"]}}'::jsonb,
  '1fa47d0677bbfc50808f0a67b8cdbc55760789748c35dc481d5390ba43c7665f'
)
