  'noi-than-001',
  '{"schema_version":"1.0.0","case_id":"noi-than-001","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-kdigo-aki-2012","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/22890468/","title":"KDIGO Clinical Practice Guideline for Acute Kidney Injury. Kidney Int Suppl 2012.","organization":null,"year_version":null,"citation":"KDIGO Clinical Practice Guideline for Acute Kidney Injury. Kidney Int Suppl 2012.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-than-001-2","resource_type":"other","source":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị một số bệnh về thận, tiết niệu (Quyết định 3931/QĐ-BYT, 2015).","title":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị một số bệnh về thận, tiết niệu (Quyết định 3931/QĐ-BYT, 2015).","organization":null,"year_version":null,"citation":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị một số bệnh về thận, tiết niệu (Quyết định 3931/QĐ-BYT, 2015).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-than-001-3","resource_type":"textbook","source":"Giáo trình Nội khoa, bộ môn Nội, các trường đại học Y Việt Nam.","title":"Giáo trình Nội khoa, bộ môn Nội, các trường đại học Y Việt Nam.","organization":null,"year_version":null,"citation":"Giáo trình Nội khoa, bộ môn Nội, các trường đại học Y Việt Nam.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"essential"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Tổn thương thận cấp sau thận do tắc nghẽn tiết niệu","credit":"none"},{"text":"Viêm cầu thận tiến triển nhanh","credit":"none"},{"text":"Tổn thương thận cấp trước thận do giảm thể tích, có yếu tố thuốc làm nặng","credit":"full"},{"text":"Hoại tử ống thận cấp do thiếu máu kéo dài","credit":"none"}]},"action_options":[{"text":"Đánh giá thể tích, bắt đầu bù dịch tinh thể đường tĩnh mạch và theo dõi nước tiểu từng giờ","time_minutes":2,"grade":"critical","rationale":"Nguyên nhân trước thận chủ yếu do giảm thể tích, cần phục hồi tưới máu thận sớm."},{"text":"Ngừng tạm thời NSAID, ức chế men chuyển và lợi tiểu","time_minutes":2,"grade":"critical","rationale":"Các thuốc này làm giảm tưới máu cầu thận và làm nặng tổn thương."},{"text":"Làm điện tâm đồ, theo dõi kali, điều chỉnh rối loạn điện giải và toan chuyển hóa","time_minutes":2,"grade":"recommended","rationale":"Kali 5,3 mmol/L và HCO3 17 mmol/L cần theo dõi sát."},{"text":"Siêu âm tiết niệu và tính FeNa để phân biệt trước thận với tại thận","time_minutes":2,"grade":"recommended","rationale":"FeNa dưới 1% và tỷ trọng cao phù hợp trước thận."},{"text":"Dùng kháng sinh khi có bằng chứng nhiễm khuẩn, hiệu chỉnh liều theo eGFR","time_minutes":1,"grade":"recommended","rationale":"Chưa có dữ kiện nhiễm khuẩn; cần hiệu chỉnh liều mọi thuốc thải qua thận."},{"text":"Truyền furosemid liều cao và tiếp tục ibuprofen để giảm đau gối","time_minutes":0,"grade":"harmful","rationale":"Làm giảm thể tích và độc thận thêm, có thể gây hoại tử ống thận."}],"teaching_explanation":"Tổn thương thận cấp trước thận đáp ứng với bù dịch, điển hình là creatinin tăng, tỷ trọng nước tiểu cao, Na niệu thấp, FeNa dưới 1%. Luôn rà soát thuốc (NSAID, ức chế men chuyển, lợi tiểu) và loại trừ tắc nghẽn bằng siêu âm."}'::jsonb,
  '2969f2d94b4a3fb97641101c8a2ce0a5935516f0c52c211fd301e415643dd5fc'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-than-002',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-than-002","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Phù toàn thân, nước tiểu nhiều bọt","setting":"giuong","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":28,"sex":"nam","patient_label":"Người bệnh mô phỏng N14"},"presentation":{"intro":"Người bệnh nam 28 tuổi nhập khoa Thận vì phù mặt, phù hai chân tăng dần 3 tuần, nước tiểu nhiều bọt.","place":null,"clock":null,"night":false},"vitals":{"hr":88,"sbp":124,"dbp":78,"rr":20,"temperature_c":36.8,"spo2":97},"history":[{"question":"Phù xuất hiện thế nào và có ảnh hưởng gì?","response":"Phù mí mắt buổi sáng rồi phù hai chân, tăng 6 kg trong 3 tuần, bụng căng hơn."},{"question":"Nước tiểu có thay đổi gì không?","response":"Nước tiểu nhiều bọt lâu tan, lượng hơi ít; không tiểu máu, không tiểu buốt."},{"question":"Có nhiễm trùng, dùng thuốc, dị ứng trước đó không?","response":"Viêm họng cách đây 6 tuần, tự mua kháng sinh; không dùng NSAID; không dị ứng."},{"question":"Có sốt, đau khớp, phát ban, rụng tóc, loét miệng không?","response":"Không."},{"question":"Có khó thở, đau ngực hoặc đau, sưng một bên chân không?","response":"Hơi khó thở khi nằm thấp; không đau ngực; hai chân phù đối xứng, không đau."},{"question":"Tiền sử bệnh thận, đái tháo đường, tăng huyết áp, viêm gan B, HIV?","response":"Không rõ; chưa từng xét nghiệm."},{"question":"Gia đình có ai mắc bệnh thận không?","response":"Không."}],"examination":[{"group":"K","item":"Phù","finding":"Phù mềm, ấn lõm, mặt, hai chân đến đùi, bìu phù, báng bụng lượng ít."},{"group":"K","item":"Phổi và tim","finding":"Rì rào phế nang giảm hai đáy, gõ đục nhẹ; tim đều, không tiếng thổi."},{"group":"K","item":"Tĩnh mạch cổ, gan, bụng","finding":"Tĩnh mạch cổ không nổi; gan không to; dịch tự do bụng ít."},{"group":"K","item":"Chân","finding":"Hai chân phù đối xứng, không nóng đỏ, không đau bắp chân."}],"investigations":[{"name":"Tổng phân tích nước tiểu và protein niệu 24 giờ","duration_minutes":10,"result":"Protein niệu 4+, protein 24 giờ 7,2 g; không hồng cầu, thấy trụ mỡ."},{"name":"Albumin, protein toàn phần, cholesterol, triglycerid máu","duration_minutes":10,"result":"Albumin 17 g/L; protein toàn phần 42 g/L; cholesterol toàn phần 11,2 mmol/L; triglycerid 3,8 mmol/L."},{"name":"Creatinin, ure, eGFR, điện giải","duration_minutes":10,"result":"Creatinin 82 umol/L, eGFR 118; Na 132 mmol/L; K 3,8 mmol/L."},{"name":"Kháng thể kháng nhân, bổ thể, HBsAg, anti-HCV, HIV, kháng thể kháng PLA2R","duration_minutes":10,"result":"Kháng thể kháng nhân âm tính; C3, C4 bình thường; HBsAg, anti-HCV, HIV âm tính; anti-PLA2R âm tính."},{"name":"Siêu âm thận","duration_minutes":15,"result":"Hai thận kích thước bình thường, đậm độ vỏ bình thường."},{"name":"Sinh thiết thận ngay lúc đang phù nặng và rối loạn đông máu chưa kiểm soát","duration_minutes":10,"result":"Chỉ làm khi có chỉ định và điều kiện an toàn; không phải ưu tiên tức thời."}],"choices":{"diagnosis":{"ydx":["Suy tim phải gây phù","Hội chứng thận hư nguyên phát, nghi bệnh cầu thận thay đổi tối thiểu hoặc xơ hóa ổ cạnh sinh, cần sinh thiết thận","Xơ gan mất bù gây phù và báng bụng","Viêm cầu thận cấp hậu nhiễm liên cầu"]},"actions":["Tầm soát nguyên nhân thứ phát: lupus, viêm gan B, C, HIV, thuốc, đái tháo đường","Dùng NSAID giảm đau và truyền dịch nhiều để làm nặng phù đỡ","Hạn chế muối, dùng lợi tiểu quai, ức chế men chuyển để giảm protein niệu","Đánh giá nguy cơ huyết khối và cân nhắc chống đông dự phòng khi albumin rất thấp","Xác định hội chứng thận hư bằng protein niệu 24 giờ, albumin máu, lipid máu","Hội chẩn thận học, chuẩn bị sinh thiết thận khi đủ điều kiện"]}}'::jsonb,
  '5384502b81f131f0b42bb600defc982427dae52afa8513a7e64fe78ce7c48c0f'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

