  '{"schema_version":"1.0.0","case_id":"noi-than-002","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-than-002-1","resource_type":"other","source":"KDIGO 2021 Clinical Practice Guideline for the Management of Glomerular Diseases. Kidney Int 2021.","title":"KDIGO 2021 Clinical Practice Guideline for the Management of Glomerular Diseases. Kidney Int 2021.","organization":null,"year_version":null,"citation":"KDIGO 2021 Clinical Practice Guideline for the Management of Glomerular Diseases. Kidney Int 2021.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-than-002-2","resource_type":"other","source":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị bệnh thận, tiết niệu (Quyết định 3931/QĐ-BYT, 2015).","title":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị bệnh thận, tiết niệu (Quyết định 3931/QĐ-BYT, 2015).","organization":null,"year_version":null,"citation":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị bệnh thận, tiết niệu (Quyết định 3931/QĐ-BYT, 2015).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-than-002-3","resource_type":"textbook","source":"Giáo trình Nội khoa, bộ môn Nội, các trường đại học Y Việt Nam.","title":"Giáo trình Nội khoa, bộ môn Nội, các trường đại học Y Việt Nam.","organization":null,"year_version":null,"citation":"Giáo trình Nội khoa, bộ môn Nội, các trường đại học Y Việt Nam.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Hội chứng thận hư nguyên phát, nghi bệnh cầu thận thay đổi tối thiểu hoặc xơ hóa ổ cạnh sinh, cần sinh thiết thận","credit":"full"},{"text":"Viêm cầu thận cấp hậu nhiễm liên cầu","credit":"none"},{"text":"Suy tim phải gây phù","credit":"none"},{"text":"Xơ gan mất bù gây phù và báng bụng","credit":"none"}]},"action_options":[{"text":"Xác định hội chứng thận hư bằng protein niệu 24 giờ, albumin máu, lipid máu","time_minutes":2,"grade":"critical","rationale":"Protein niệu trên 3,5 g/24 giờ, albumin dưới 30 g/L, phù và tăng lipid máu là tiêu chuẩn chẩn đoán."},{"text":"Tầm soát nguyên nhân thứ phát: lupus, viêm gan B, C, HIV, thuốc, đái tháo đường","time_minutes":2,"grade":"critical","rationale":"Cần loại trừ nguyên nhân thứ phát trước khi dùng thuốc ức chế miễn dịch."},{"text":"Hạn chế muối, dùng lợi tiểu quai, ức chế men chuyển để giảm protein niệu","time_minutes":2,"grade":"recommended","rationale":"Giảm phù và bảo vệ cầu thận."},{"text":"Hội chẩn thận học, chuẩn bị sinh thiết thận khi đủ điều kiện","time_minutes":2,"grade":"recommended","rationale":"Người lớn thường cần mô bệnh học để chọn điều trị."},{"text":"Đánh giá nguy cơ huyết khối và cân nhắc chống đông dự phòng khi albumin rất thấp","time_minutes":2,"grade":"recommended","rationale":"Mất antithrombin và tăng yếu tố đông máu gây tăng đông."},{"text":"Dùng NSAID giảm đau và truyền dịch nhiều để làm nặng phù đỡ","time_minutes":0,"grade":"harmful","rationale":"NSAID làm nặng tổn thương thận và giữ muối nước."}],"teaching_explanation":"Hội chẩn hội chứng thận hư cần bốn tiêu chuẩn: phù, protein niệu trên 3,5 g/24 giờ, albumin máu dưới 30 g/L, tăng lipid máu. Ở người lớn phải tìm nguyên nhân thứ phát và thường cần sinh thiết thận; nhớ biến chứng huyết khối và nhiễm trùng."}'::jsonb,
