insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-than-003',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-than-003","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Sốt rét run và đau hông lưng phải, tiểu buốt","setting":"giuong","level":"Dễ","track":"noi","mode":"tay","specialty":null,"demographics":{"age":31,"sex":"nữ","patient_label":"Người bệnh mô phỏng N15"},"presentation":{"intro":"Người bệnh nữ 31 tuổi nhập viện vì sốt cao rét run, đau hông lưng phải và tiểu buốt, tiểu rắt ba ngày.","place":null,"clock":null,"night":false},"vitals":{"hr":104,"sbp":108,"dbp":64,"rr":20,"temperature_c":39.4,"spo2":98},"history":[{"question":"Triệu chứng tiết niệu bắt đầu thế nào?","response":"Ba ngày nay tiểu buốt, tiểu rắt, nước tiểu đục; sau đó đau âm ỉ hông lưng phải."},{"question":"Sốt và rét run diễn tiến ra sao?","response":"Sốt cao rét run từ hôm qua, uống paracetamol đỡ ít rồi sốt lại; có buồn nôn."},{"question":"Có nôn nhiều, không ăn uống được, choáng váng khi đứng không?","response":"Nôn 2 lần, uống ít nước, hơi choáng khi đứng dậy."},{"question":"Có đang mang thai, đái tháo đường, sỏi tiết niệu hoặc dị tật tiết niệu không?","response":"Không mang thai; không đái tháo đường; chưa từng sỏi."},{"question":"Có từng nhiễm trùng tiểu, dùng kháng sinh gần đây hoặc đặt ống thông không?","response":"Một lần viêm bàng quang năm ngoái, tự khỏi; không dùng kháng sinh gần đây; không đặt ống thông."},{"question":"Có tiểu máu, ra khí hư, đau bụng dưới không?","response":"Không tiểu máu; không khí hư bất thường; đau bụng dưới nhẹ."},{"question":"Có dị ứng thuốc không?","response":"Dị ứng penicillin dạng phát ban nhẹ khi còn nhỏ."}],"examination":[{"group":"K","item":"Dấu hiệu sinh tồn và toàn trạng","finding":"Sốt cao, mạch nhanh, vẻ mặt mệt, khô môi nhẹ, chưa lú lẫn."},{"group":"K","item":"Vùng hông lưng","finding":"Rung thận phải dương tính, ấn góc sườn-sống lưng phải đau."},{"group":"K","item":"Bụng","finding":"Bụng mềm, ấn đau nhẹ hạ vị, không phản ứng thành bụng."},{"group":"K","item":"Tim phổi","finding":"Tim nhanh đều, phổi trong."}],"investigations":[{"name":"Tổng phân tích nước tiểu","duration_minutes":10,"result":"Bạch cầu niệu 3+, nitrit dương tính, hồng cầu niệu 1+, thấy trụ bạch cầu."},{"name":"Cấy nước tiểu và kháng sinh đồ","duration_minutes":10,"result":"Đã lấy mẫu giữa dòng trước kháng sinh; kết quả đang chờ (sau đó E. coli)."},{"name":"Công thức máu, CRP, creatinin, điện giải","duration_minutes":10,"result":"Bạch cầu 17,8 G/L (bạch cầu đa nhân 88%); CRP 156 mg/L; creatinin 78 umol/L; K 3,6 mmol/L."},{"name":"Cấy máu hai bộ","duration_minutes":10,"result":"Đã lấy hai bộ trước kháng sinh, kết quả đang chờ."},{"name":"Siêu âm hệ tiết niệu","duration_minutes":15,"result":"Thận phải to nhẹ, không giãn đài bể thận, không sỏi, không ổ tụ dịch."},{"name":"CT bụng có cản quang ngay lập tức trước khi bắt đầu điều trị","duration_minutes":40,"result":"Không cần thiết nếu chưa có dấu hiệu biến chứng hoặc không đáp ứng sau 48 đến 72 giờ."}],"choices":{"diagnosis":{"ydx":["Viêm thận bể thận cấp không biến chứng, nhiều khả năng do E. coli","Cơn đau quặn thận do sỏi niệu quản","Viêm bàng quang cấp đơn thuần","Viêm phần phụ cấp"]},"actions":["Chỉ dùng kháng sinh đường uống một liều rồi cho về mà không cấy hay theo dõi","Siêu âm để loại trừ tắc nghẽn hoặc ổ áp xe","Chọn kháng sinh phù hợp tiền sử dị ứng và dịch tễ kháng thuốc địa phương","Đánh giá lại sau 48 đến 72 giờ; nếu không đáp ứng thì chụp CT","Bù dịch đường tĩnh mạch, hạ sốt, giảm đau","Lấy nước tiểu giữa dòng và máu cấy trước, rồi bắt đầu kháng sinh tĩnh mạch sớm"]}}'::jsonb,
  '372f4dfc81a91e35fd0075bc506713695244052e5cddd629e81dc55eb4a52a5a'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-than-003',
  '{"schema_version":"1.0.0","case_id":"noi-than-003","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-than-003-1","resource_type":"other","source":"EAU Guidelines on Urological Infections. European Association of Urology 2024.","title":"EAU Guidelines on Urological Infections. European Association of Urology 2024.","organization":null,"year_version":null,"citation":"EAU Guidelines on Urological Infections. European Association of Urology 2024.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-than-003-2","resource_type":"other","source":"IDSA/ESCMID. International Clinical Practice Guidelines for the Treatment of Acute Uncomplicated Cystitis and Pyelonephritis in Women. Clin Infect Dis 2011.","title":"IDSA/ESCMID. International Clinical Practice Guidelines for the Treatment of Acute Uncomplicated Cystitis and Pyelonephritis in Women. Clin Infect Dis 2011.","organization":null,"year_version":null,"citation":"IDSA/ESCMID. International Clinical Practice Guidelines for the Treatment of Acute Uncomplicated Cystitis and Pyelonephritis in Women. Clin Infect Dis 2011.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-708-2015","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-708-qd-byt-bo-y-te-93000-d1.html","title":"Bộ Y tế. Hướng dẫn sử dụng kháng sinh (Quyết định 708/QĐ-BYT, 2015).","organization":null,"year_version":null,"citation":"Bộ Y tế. Hướng dẫn sử dụng kháng sinh (Quyết định 708/QĐ-BYT, 2015).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-than-003-4","resource_type":"textbook","source":"Giáo trình Nội khoa, bộ môn Nội, các trường đại học Y Việt Nam.","title":"Giáo trình Nội khoa, bộ môn Nội, các trường đại học Y Việt Nam.","organization":null,"year_version":null,"citation":"Giáo trình Nội khoa, bộ môn Nội, các trường đại học Y Việt Nam.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,6],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"essential"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm bàng quang cấp đơn thuần","credit":"none"},{"text":"Viêm thận bể thận cấp không biến chứng, nhiều khả năng do E. coli","credit":"full"},{"text":"Cơn đau quặn thận do sỏi niệu quản","credit":"none"},{"text":"Viêm phần phụ cấp","credit":"none"}]},"action_options":[{"text":"Lấy nước tiểu giữa dòng và máu cấy trước, rồi bắt đầu kháng sinh tĩnh mạch sớm","time_minutes":2,"grade":"critical","rationale":"Điều trị kháng sinh theo kinh nghiệm không được trì hoãn khi có sốt cao và dấu hiệu nhiễm khuẩn toàn thân."},{"text":"Bù dịch đường tĩnh mạch, hạ sốt, giảm đau","time_minutes":2,"grade":"critical","rationale":"Có mất nước nhẹ và nhịp tim nhanh."},{"text":"Chọn kháng sinh phù hợp tiền sử dị ứng và dịch tễ kháng thuốc địa phương","time_minutes":2,"grade":"recommended","rationale":"Người bệnh dị ứng penicillin nhẹ; ưu tiên cephalosporin thế hệ 3 hoặc fluoroquinolone theo kháng sinh đồ."},{"text":"Siêu âm để loại trừ tắc nghẽn hoặc ổ áp xe","time_minutes":2,"grade":"recommended","rationale":"Siêu âm là bước đầu, không xâm lấn."},{"text":"Đánh giá lại sau 48 đến 72 giờ; nếu không đáp ứng thì chụp CT","time_minutes":2,"grade":"recommended","rationale":"Thất bại điều trị gợi ý biến chứng hoặc kháng thuốc."},{"text":"Chỉ dùng kháng sinh đường uống một liều rồi cho về mà không cấy hay theo dõi","time_minutes":0,"grade":"harmful","rationale":"Có nguy cơ nhiễm khuẩn huyết và tổn thương thận."}],"teaching_explanation":"Viêm thận bể thận cấp biểu hiện sốt, đau hông lưng, rung thận dương tính kèm triệu chứng tiết niệu dưới; nước tiểu có bạch cầu, nitrit dương tính. Phải cấy nước tiểu, cấy máu trước kháng sinh, điều trị sớm và loại trừ tắc nghẽn khi bệnh nặng hoặc không đáp ứng."}'::jsonb,
  '1d7a28028af3f489433551444d8ca818dc207c602ff89e3e879aa88651be7dbd'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-than-kinh-001',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-than-kinh-001","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Liệt nửa người phải và nói khó khởi phát đột ngột","setting":"giuong","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":68,"sex":"nam","patient_label":"Người bệnh mô phỏng N16"},"presentation":{"intro":"Người bệnh nam 68 tuổi được đưa vào cấp cứu sau khi đột ngột yếu nửa người phải và nói khó, thời điểm khởi phát được người nhà xác định rõ khoảng 90 phút trước.","place":null,"clock":null,"night":false},"vitals":{"hr":92,"sbp":172,"dbp":96,"rr":18,"temperature_c":36.9,"spo2":96},"history":[{"question":"Triệu chứng khởi phát lúc mấy giờ, đang làm gì, có diễn tiến thế nào?","response":"Khoảng 90 phút trước, đang ăn sáng thì rơi đũa, yếu tay chân phải, nói khó và méo miệng; không tự đỡ."},{"question":"Có đau đầu dữ dội, nôn, co giật hoặc chấn thương đầu không?","response":"Không đau đầu dữ dội, không nôn, không co giật, không té ngã trước đó."},{"question":"Có bệnh nền như tăng huyết áp, đái tháo đường, rung nhĩ, bệnh tim không?","response":"Tăng huyết áp 10 năm dùng thuốc không đều; đái tháo đường típ 2; chưa biết bệnh tim."},{"question":"Đang dùng thuốc chống đông hoặc kháng tiểu cầu không?","response":"Không dùng thuốc chống đông; thỉnh thoảng uống aspirin."},{"question":"Có phẫu thuật, xuất huyết tiêu hóa hoặc chấn thương lớn trong 3 tháng qua không?","response":"Không."},{"question":"Có hút thuốc, uống rượu không?","response":"Hút thuốc 30 gói-năm, uống rượu ít."},{"question":"Có từng thoáng yếu liệt, nói khó rồi tự hết trước đây không?","response":"Một tuần trước có tê yếu tay phải khoảng 15 phút rồi tự hết, không đi khám."}],"examination":[{"group":"K","item":"Tri giác và thang điểm NIHSS","finding":"Tỉnh, GCS 14 (E4 V4 M6), nói khó, liệt mặt phải kiểu trung ương, liệt tay phải 1/5, chân phải 3/5; NIHSS 14."},{"group":"K","item":"Tim mạch","finding":"Nhịp tim không đều, không tiếng thổi; mạch ngoại biên đều hai bên."},{"group":"K","item":"Thần kinh khác","finding":"Phản xạ da bàn chân phải duỗi, đồng tử đều phản xạ tốt, không cứng gáy, không phù gai."},{"group":"K","item":"Hô hấp và bụng","finding":"Phổi trong, bụng mềm."}],"investigations":[{"name":"CT sọ não không cản quang khẩn","duration_minutes":40,"result":"Không có xuất huyết; mờ ranh giới thùy đảo phải mức nhẹ, điểm ASPECTS 9."},{"name":"Đường huyết mao mạch ngay lập tức","duration_minutes":10,"result":"Glucose 8,2 mmol/L."},{"name":"Công thức máu, đông máu, INR, creatinin","duration_minutes":10,"result":"Tiểu cầu 220 G/L; INR 1,0; aPTT bình thường; creatinin 92 umol/L."},{"name":"Điện tâm đồ","duration_minutes":10,"result":"Rung nhĩ đáp ứng thất khoảng 92 lần/phút."},{"name":"CT mạch máu não và mạch cảnh","duration_minutes":40,"result":"Tắc đoạn M1 động mạch não giữa trái; các mạch cảnh thông."},{"name":"Chọc dò dịch não tủy để loại trừ viêm màng não trước khi quyết định điều trị","duration_minutes":10,"result":"Không có chỉ định, làm chậm tái thông."}],"choices":{"diagnosis":{"ydx":["Nhồi máu não cấp vùng động mạch não giữa trái, nghi nguyên nhân thuyên tắc từ rung nhĩ","Xuất huyết não do tăng huyết áp","Hạ đường huyết gây liệt nửa người","Cơn thiếu máu não thoáng qua đã hồi phục"]},"actions":["Kích hoạt báo động đột quỵ, đo NIHSS, đường huyết và chụp CT sọ không cản quang khẩn","Chụp CT mạch và hội chẩn can thiệp thần kinh để lấy huyết khối cơ học do tắc M1","Hội chẩn tim mạch về rung nhĩ và dự phòng bằng thuốc chống đông đường uống sau giai đoạn cấp","Theo dõi thần kinh, huyết áp, đường huyết, nuốt và tư thế đầu","Kiểm soát huyết áp dưới 185/110 mmHg rồi truyền alteplase đường tĩnh mạch nếu không có chống chỉ định","Cho thêm aspirin và heparin ngay trước khi quyết định tiêu sợi huyết"]}}'::jsonb,
  'e9c52270a9aad29db9fd69467f46f31de2650edcf3f004e800c91db93e870dee'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
