values (
  'noi-than-kinh-001',
  '{"schema_version":"1.0.0","case_id":"noi-than-kinh-001","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ais-aha-2019-63a4cc1eb291","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/31662037/","title":"Powers WJ, et al. 2019 Update to the 2018 Guidelines for the Early Management of Acute Ischemic Stroke. AHA/ASA. Stroke 2019;50:e344.","organization":null,"year_version":null,"citation":"Powers WJ, et al. 2019 Update to the 2018 Guidelines for the Early Management of Acute Ischemic Stroke. AHA/ASA. Stroke 2019;50:e344.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-5331-2020","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-5331-qd-byt-huong-dan-chan-doan-va-xu-tri-dot-quy-nao-196062-d1.html","title":"Bộ Y tế. Hướng dẫn chẩn đoán và xử trí đột quỵ não (Quyết định 5331/QĐ-BYT, 2020).","organization":null,"year_version":null,"citation":"Bộ Y tế. Hướng dẫn chẩn đoán và xử trí đột quỵ não (Quyết định 5331/QĐ-BYT, 2020).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-than-kinh-001-3","resource_type":"textbook","source":"Giáo trình Thần kinh học, bộ môn Thần kinh, các trường đại học Y Việt Nam.","title":"Giáo trình Thần kinh học, bộ môn Thần kinh, các trường đại học Y Việt Nam.","organization":null,"year_version":null,"citation":"Giáo trình Thần kinh học, bộ môn Thần kinh, các trường đại học Y Việt Nam.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,6],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"essential"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Xuất huyết não do tăng huyết áp","credit":"none"},{"text":"Cơn thiếu máu não thoáng qua đã hồi phục","credit":"none"},{"text":"Nhồi máu não cấp vùng động mạch não giữa trái, nghi nguyên nhân thuyên tắc từ rung nhĩ","credit":"full"},{"text":"Hạ đường huyết gây liệt nửa người","credit":"none"}]},"action_options":[{"text":"Kích hoạt báo động đột quỵ, đo NIHSS, đường huyết và chụp CT sọ không cản quang khẩn","time_minutes":2,"grade":"critical","rationale":"Thời gian là não; cần loại trừ xuất huyết và đánh giá chỉ định tái thông."},{"text":"Kiểm soát huyết áp dưới 185/110 mmHg rồi truyền alteplase đường tĩnh mạch nếu không có chống chỉ định","time_minutes":2,"grade":"critical","rationale":"Khởi phát 90 phút, không chống chỉ định, đủ tiêu chuẩn tiêu sợi huyết."},{"text":"Chụp CT mạch và hội chẩn can thiệp thần kinh để lấy huyết khối cơ học do tắc M1","time_minutes":2,"grade":"recommended","rationale":"Tắc mạch lớn vùng trước, NIHSS cao, nên lấy huyết khối cơ học."},{"text":"Theo dõi thần kinh, huyết áp, đường huyết, nuốt và tư thế đầu","time_minutes":2,"grade":"recommended","rationale":"Phòng biến chứng chảy máu, hít sặc, tăng đường huyết."},{"text":"Hội chẩn tim mạch về rung nhĩ và dự phòng bằng thuốc chống đông đường uống sau giai đoạn cấp","time_minutes":2,"grade":"recommended","rationale":"Rung nhĩ là nguyên nhân thuyên tắc, dự phòng thứ phát cần sau thời điểm an toàn."},{"text":"Cho thêm aspirin và heparin ngay trước khi quyết định tiêu sợi huyết","time_minutes":0,"grade":"harmful","rationale":"Tăng nguy cơ xuất huyết, làm mất chỉ định tiêu sợi huyết."}],"teaching_explanation":"Trong nhồi máu não cấp, quyết định đầu tiên dựa vào thời điểm khởi phát, CT sọ loại trừ xuất huyết và chống chỉ định. Tiêu sợi huyết trong 4,5 giờ và lấy huyết khối cơ học khi tắc mạch lớn vùng trước. Tìm nguyên nhân (rung nhĩ) để dự phòng thứ phát."}'::jsonb,
  '13db70f4c86a9c15a28443ffd0f0eb54e8887e1af3eb1316cfafdaa867e65385'
)
