insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-than-kinh-002',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-than-kinh-002","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau đầu dữ dội, nôn và yếu nửa người trái trên nền huyết áp cao","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":58,"sex":"nam","patient_label":"Người bệnh mô phỏng N17"},"presentation":{"intro":"Người bệnh nam 58 tuổi được đưa vào cấp cứu sau khi đột ngột đau đầu dữ dội, nôn và yếu nửa người trái khi đang làm việc.","place":null,"clock":null,"night":false},"vitals":{"hr":96,"sbp":218,"dbp":118,"rr":20,"temperature_c":37.1,"spo2":96},"history":[{"question":"Triệu chứng khởi phát thế nào?","response":"Đang làm vườn thì đau đầu dữ dội bên phải, nôn hai lần, rồi yếu tay chân trái và nói ngọng; khoảng 2 giờ trước."},{"question":"Có chấn thương đầu, co giật, mất ý thức không?","response":"Không té ngã; có lơ mơ từng lúc; không co giật."},{"question":"Tiền sử tăng huyết áp và điều trị?","response":"Tăng huyết áp 12 năm, uống thuốc không đều, mấy tuần nay bỏ thuốc."},{"question":"Có dùng thuốc chống đông, kháng tiểu cầu, rượu hoặc ma túy không?","response":"Không chống đông; uống rượu nhiều dịp lễ; không ma túy."},{"question":"Có bệnh gan, rối loạn đông máu, đột quỵ trước đây không?","response":"Không."},{"question":"Có sốt, cứng gáy, chóng mặt, đau thắt ngực không?","response":"Không."},{"question":"Có đái tháo đường hoặc rối loạn mỡ máu không?","response":"Chưa biết, chưa xét nghiệm."}],"examination":[{"group":"K","item":"Tri giác","finding":"GCS 11 (E3 V3 M5) lúc vào, đồng tử hai bên đều, phản xạ ánh sáng tốt."},{"group":"K","item":"Thần kinh vận động","finding":"Liệt nửa người trái 2/5, liệt mặt trái trung ương, Babinski trái dương tính."},{"group":"K","item":"Dấu hiệu màng não và đáy mắt","finding":"Gáy mềm; đáy mắt có hẹp động mạch, chưa phù gai thị."},{"group":"K","item":"Tim phổi và bụng","finding":"Tim đều, T2 vang ở ổ động mạch chủ; phổi trong; bụng mềm."}],"investigations":[{"name":"CT sọ não không cản quang khẩn","duration_minutes":40,"result":"Khối máu tụ nhân bèo và bao trong phải khoảng 38 mL, tràn vào não thất bên nhẹ, đẩy lệch đường giữa 3 mm."},{"name":"Công thức máu, đông máu, INR, đường huyết, điện giải, chức năng gan thận","duration_minutes":10,"result":"Tiểu cầu 205 G/L; INR 1,0; glucose 7,0 mmol/L; creatinin 110 umol/L; K 3,7 mmol/L."},{"name":"Điện tâm đồ và men tim","duration_minutes":10,"result":"Phì đại thất trái, không có ST chênh; troponin bình thường."},{"name":"CT mạch máu não","duration_minutes":40,"result":"Không thấy phình mạch hay dị dạng mạch máu; không dấu hiệu chấm (spot sign)."},{"name":"X quang ngực","duration_minutes":10,"result":"Bóng tim hơi to; không tổn thương phổi cấp."},{"name":"Chọc dò dịch não tủy","duration_minutes":10,"result":"Chống chỉ định khi có khối choán chỗ và nghi tăng áp lực nội sọ."}],"choices":{"diagnosis":{"ydx":["Xuất huyết não vùng nhân bèo và bao trong phải do tăng huyết áp","Nhồi máu não vùng động mạch não giữa phải","Xuất huyết dưới nhện do vỡ phình mạch","Cơn thiếu máu não thoáng qua"]},"actions":["Đảo ngược rối loạn đông máu nếu có; ở ca này INR và tiểu cầu bình thường nên chỉ cần theo dõi","Hội chẩn ngoại thần kinh khi xấu dần, tràn vào não thất gây não úng thủy hoặc khối máu tụ lớn chèn ép","Bảo vệ đường thở, theo dõi monitor, chụp CT sọ não khẩn","Nâng đầu cao 30 độ, tránh hạ natri, kiểm soát sốt, đường huyết, nôn","Truyền alteplase hoặc cho aspirin, heparin ngay khi chưa chụp CT","Hạ huyết áp có kiểm soát bằng thuốc truyền tĩnh mạch (nicardipin hoặc labetalol) để tâm thu khoảng 140 mmHg"]}}'::jsonb,
  '184a888900c8c47151a8d1b866f0fbe0a2e4d544c17c9c4eee9c33b93a404979'
)
