insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-than-kinh-002',
  '{"schema_version":"1.0.0","case_id":"noi-than-kinh-002","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ich-aha-2022","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/35579034/","title":"Greenberg SM, et al. 2022 Guideline for the Management of Patients With Spontaneous Intracerebral Hemorrhage. AHA/ASA. Stroke 2022;53:e282.","organization":null,"year_version":null,"citation":"Greenberg SM, et al. 2022 Guideline for the Management of Patients With Spontaneous Intracerebral Hemorrhage. AHA/ASA. Stroke 2022;53:e282.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-5331-2020","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-5331-qd-byt-huong-dan-chan-doan-va-xu-tri-dot-quy-nao-196062-d1.html","title":"Bộ Y tế. Hướng dẫn chẩn đoán và xử trí đột quỵ não (Quyết định 5331/QĐ-BYT, 2020).","organization":null,"year_version":null,"citation":"Bộ Y tế. Hướng dẫn chẩn đoán và xử trí đột quỵ não (Quyết định 5331/QĐ-BYT, 2020).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-than-kinh-002-3","resource_type":"textbook","source":"Giáo trình Thần kinh học, bộ môn Thần kinh, các trường đại học Y Việt Nam.","title":"Giáo trình Thần kinh học, bộ môn Thần kinh, các trường đại học Y Việt Nam.","organization":null,"year_version":null,"citation":"Giáo trình Thần kinh học, bộ môn Thần kinh, các trường đại học Y Việt Nam.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Nhồi máu não vùng động mạch não giữa phải","credit":"none"},{"text":"Xuất huyết dưới nhện do vỡ phình mạch","credit":"none"},{"text":"Cơn thiếu máu não thoáng qua","credit":"none"},{"text":"Xuất huyết não vùng nhân bèo và bao trong phải do tăng huyết áp","credit":"full"}]},"action_options":[{"text":"Bảo vệ đường thở, theo dõi monitor, chụp CT sọ não khẩn","time_minutes":2,"grade":"critical","rationale":"GCS 11 cần bảo vệ đường thở; CT phân biệt xuất huyết và nhồi máu."},{"text":"Hạ huyết áp có kiểm soát bằng thuốc truyền tĩnh mạch (nicardipin hoặc labetalol) để tâm thu khoảng 140 mmHg","time_minutes":2,"grade":"critical","rationale":"Giảm nguy cơ lan rộng khối máu tụ mà không làm giảm tưới máu não."},{"text":"Đảo ngược rối loạn đông máu nếu có; ở ca này INR và tiểu cầu bình thường nên chỉ cần theo dõi","time_minutes":2,"grade":"recommended","rationale":"Cần xác nhận không dùng thuốc chống đông trước khi quyết định."},{"text":"Nâng đầu cao 30 độ, tránh hạ natri, kiểm soát sốt, đường huyết, nôn","time_minutes":2,"grade":"recommended","rationale":"Giảm tăng áp lực nội sọ và biến chứng thứ phát."},{"text":"Hội chẩn ngoại thần kinh khi xấu dần, tràn vào não thất gây não úng thủy hoặc khối máu tụ lớn chèn ép","time_minutes":2,"grade":"recommended","rationale":"Có thể cần dẫn lưu não thất hoặc mở sọ giải ép."},{"text":"Truyền alteplase hoặc cho aspirin, heparin ngay khi chưa chụp CT","time_minutes":0,"grade":"harmful","rationale":"Nếu xuất huyết sẽ gây tử vong nhanh."}],"teaching_explanation":"Đột quỵ cấp luôn cần chụp CT sọ não để phân biệt xuất huyết và nhồi máu trước khi dùng thuốc. Xuất huyết não do tăng huyết áp thường ở nhân bèo, bao trong, đồi thị, cầu não, tiểu não; xử trí bao gồm bảo vệ đường thở, hạ huyết áp có kiểm soát, giảm tăng áp lực nội sọ và hội chẩn ngoại."}'::jsonb,
  '5a39f5f41259f99360da791b2330d302d9d9fb147998f6eed88954100db9c9bc'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-huyet-hoc-001',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-huyet-hoc-001","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Mệt mỏi, hoa mắt và rong kinh kéo dài","setting":"giuong","level":"Dễ","track":"noi","mode":"tay","specialty":null,"demographics":{"age":35,"sex":"nữ","patient_label":"Người bệnh mô phỏng N18"},"presentation":{"intro":"Người bệnh nữ 35 tuổi đến phòng khám vì mệt mỏi, hoa mắt, hồi hộp khi gắng sức nhiều tháng, kinh nguyệt ra nhiều kéo dài.","place":null,"clock":null,"night":false},"vitals":{"hr":98,"sbp":104,"dbp":62,"rr":18,"temperature_c":36.7,"spo2":98},"history":[{"question":"Mệt, hoa mắt xuất hiện từ khi nào và có tăng dần không?","response":"Khoảng 5 tháng nay mệt, hoa mắt khi leo cầu thang, hồi hộp, khó tập trung, càng ngày càng tăng."},{"question":"Chu kỳ kinh và lượng máu kinh thế nào?","response":"Kinh ra 8 đến 10 ngày, thay băng 8 đến 10 miếng/ngày, có máu cục, đã 8 tháng như vậy."},{"question":"Có tiêu ra máu, phân đen, nôn máu hoặc dùng thuốc giảm đau, kháng viêm kéo dài không?","response":"Không phân đen, không tiêu ra máu; không dùng thuốc kháng viêm."},{"question":"Chế độ ăn như thế nào, có ăn chay không?","response":"Ăn ít thịt đỏ, uống trà đặc sau bữa ăn, chưa từng dùng sắt."},{"question":"Có thèm ăn đá, đất, móng tay giòn, tóc rụng, nuốt vướng không?","response":"Hay thèm ăn đá lạnh, móng tay dễ gãy, tóc rụng nhiều."},{"question":"Có đang mang thai hoặc cho con bú, bệnh tuyến giáp, bệnh mạn tính không?","response":"Không mang thai; có 2 con, đã sinh thường; không bệnh mạn tính."},{"question":"Tiền sử gia đình về thiếu máu, bệnh huyết sắc tố?","response":"Không."}],"examination":[{"group":"K","item":"Da niêm mạc","finding":"Da xanh, niêm mạc mắt nhợt, lòng bàn tay nhợt, không vàng da."},{"group":"K","item":"Tim mạch","finding":"Tim nhanh đều, thổi tâm thu cơ năng 2/6 ở mỏm; không phù."},{"group":"K","item":"Móng và miệng","finding":"Móng khum hình thìa nhẹ, viêm góc miệng, lưỡi nhẵn bóng."},{"group":"K","item":"Bụng và hạch","finding":"Gan, lách không to, không hạch ngoại vi."}],"investigations":[{"name":"Công thức máu và chỉ số hồng cầu","duration_minutes":10,"result":"Hb 7,6 g/dL; MCV 64 fL; MCH 19 pg; MCHC 29 g/dL; RDW 19%; tiểu cầu 460 G/L; bạch cầu bình thường."},{"name":"Ferritin, sắt huyết thanh, độ bão hòa transferrin, TIBC","duration_minutes":10,"result":"Ferritin 4 ng/mL; sắt huyết thanh 4 umol/L; độ bão hòa transferrin 6%; TIBC tăng."},{"name":"Phết máu ngoại vi","duration_minutes":10,"result":"Hồng cầu nhỏ, nhược sắc, thay đổi kích thước và hình dạng, có hồng cầu hình bút chì; không có hồng cầu non."},{"name":"Xét nghiệm tìm máu ẩn trong phân và siêu âm vùng chậu","duration_minutes":15,"result":"Máu ẩn phân âm tính; siêu âm có nhân xơ tử cung 3 cm dưới niêm mạc."},{"name":"Nội soi dạ dày đại tràng để tầm soát nguyên nhân mất máu tiêu hóa","duration_minutes":20,"result":"Chỉ định thêm khi không có triệu chứng tiêu hóa và nguyên nhân rõ là rong kinh, ưu tiên xử trí sau."},{"name":"Chọc hút tủy xương để chẩn đoán thiếu máu","duration_minutes":10,"result":"Không cần thiết khi chẩn đoán đã rõ."}],"choices":{"diagnosis":{"ydx":["Thiếu máu thiếu sắt do mất máu kinh nguyệt kéo dài, nghi do nhân xơ tử cung","Thiếu máu do bệnh mạn tính","Thiếu máu bất sản","Thalassemia thể nhẹ"]},"actions":["Xác định thiếu máu thiếu sắt bằng công thức máu, ferritin và độ bão hòa transferrin","Truyền khối hồng cầu thường quy rồi cho về không tìm nguyên nhân","Bổ sung sắt nguyên tố đường uống 100 đến 200 mg/ngày hoặc cách ngày, kèm vitamin C","Tìm nguyên nhân mất máu: hỏi bệnh sử kinh nguyệt, siêu âm vùng chậu, hội chẩn sản phụ khoa","Cân nhắc sắt tĩnh mạch nếu không dung nạp hoặc không đáp ứng sắt uống","Hướng dẫn tránh uống trà, cà phê, sữa cùng bữa sắt và dặn tác dụng phụ thường gặp"]}}'::jsonb,
  '57cf582c1201629a8cab158ad3710ba52c57edb044a8e41d0a127620aa915090'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

