values (
  'noi-huyet-hoc-001',
  '{"schema_version":"1.0.0","case_id":"noi-huyet-hoc-001","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-huyet-hoc-001-1","resource_type":"other","source":"World Health Organization. Guideline on use of ferritin concentrations to assess iron status in individuals and populations. WHO 2020.","title":"World Health Organization. Guideline on use of ferritin concentrations to assess iron status in individuals and populations. WHO 2020.","organization":null,"year_version":null,"citation":"World Health Organization. Guideline on use of ferritin concentrations to assess iron status in individuals and populations. WHO 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ida-camaschella-2015-baab7910198e","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/25946282/","title":"Camaschella C. Iron-deficiency anemia. N Engl J Med 2015;372:1832-43.","organization":null,"year_version":null,"citation":"Camaschella C. Iron-deficiency anemia. N Engl J Med 2015;372:1832-43.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-huyet-hoc-001-3","resource_type":"other","source":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị thiếu máu thiếu sắt (tài liệu chuyên môn huyết học, cần đối chiếu số hiệu).","title":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị thiếu máu thiếu sắt (tài liệu chuyên môn huyết học, cần đối chiếu số hiệu).","organization":null,"year_version":null,"citation":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị thiếu máu thiếu sắt (tài liệu chuyên môn huyết học, cần đối chiếu số hiệu).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-huyet-hoc-001-4","resource_type":"textbook","source":"Giáo trình Huyết học - Truyền máu, các trường đại học Y Việt Nam.","title":"Giáo trình Huyết học - Truyền máu, các trường đại học Y Việt Nam.","organization":null,"year_version":null,"citation":"Giáo trình Huyết học - Truyền máu, các trường đại học Y Việt Nam.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"waste"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Thiếu máu thiếu sắt do mất máu kinh nguyệt kéo dài, nghi do nhân xơ tử cung","credit":"full"},{"text":"Thiếu máu do bệnh mạn tính","credit":"none"},{"text":"Thalassemia thể nhẹ","credit":"none"},{"text":"Thiếu máu bất sản","credit":"none"}]},"action_options":[{"text":"Xác định thiếu máu thiếu sắt bằng công thức máu, ferritin và độ bão hòa transferrin","time_minutes":2,"grade":"critical","rationale":"Hb thấp, MCV thấp, ferritin thấp xác định thiếu sắt."},{"text":"Tìm nguyên nhân mất máu: hỏi bệnh sử kinh nguyệt, siêu âm vùng chậu, hội chẩn sản phụ khoa","time_minutes":2,"grade":"critical","rationale":"Thiếu sắt ở phụ nữ tuổi sinh đẻ thường do rong kinh; cần điều trị nguyên nhân."},{"text":"Bổ sung sắt nguyên tố đường uống 100 đến 200 mg/ngày hoặc cách ngày, kèm vitamin C","time_minutes":2,"grade":"recommended","rationale":"Điều trị chuẩn thiếu sắt mức độ trung bình đến nặng khi dung nạp được."},{"text":"Hướng dẫn tránh uống trà, cà phê, sữa cùng bữa sắt và dặn tác dụng phụ thường gặp","time_minutes":2,"grade":"recommended","rationale":"Tăng hấp thu và tuân thủ."},{"text":"Cân nhắc sắt tĩnh mạch nếu không dung nạp hoặc không đáp ứng sắt uống","time_minutes":1,"grade":"recommended","rationale":"Không phải bước đầu ở ca này nhưng là lựa chọn khi thất bại."},{"text":"Truyền khối hồng cầu thường quy rồi cho về không tìm nguyên nhân","time_minutes":0,"grade":"harmful","rationale":"Chỉ truyền máu khi thiếu máu nặng có triệu chứng; bỏ sót nguyên nhân sẽ tái diễn."}],"teaching_explanation":"Thiếu sắt là nguyên nhân thiếu máu thường gặp nhất; chẩn đoán dựa vào Hb thấp, MCV thấp, ferritin thấp. Luôn tìm nguyên nhân mất máu (kinh nguyệt ở nữ, tiêu hóa ở nam hoặc người lớn tuổi), điều trị nguyên nhân và bổ sung sắt đủ thời gian."}'::jsonb,
