insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-nhiem-001',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-nhiem-001","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Sốt ngày thứ tư, đau bụng và nôn nhiều","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":24,"sex":"nam","patient_label":"Người bệnh mô phỏng N19"},"presentation":{"intro":"Người bệnh nam 24 tuổi sống ở vùng có dịch sốt xuất huyết, nhập khoa Nhiễm vì sốt ngày thứ tư, đau bụng, nôn nhiều, sốt giảm nhưng người mệt hơn.","place":null,"clock":null,"night":false},"vitals":{"hr":104,"sbp":100,"dbp":74,"rr":20,"temperature_c":37.4,"spo2":98},"history":[{"question":"Sốt bắt đầu từ khi nào và diễn tiến thế nào?","response":"Sốt cao liên tục 4 ngày, hôm nay sốt giảm còn 37,4 độ C nhưng người mệt lả hơn."},{"question":"Có đau bụng, nôn, chảy máu cam, chảy máu chân răng, kinh nguyệt bất thường, đi tiêu phân đen không?","response":"Đau bụng vùng thượng vị và hạ sườn phải tăng dần, nôn 5 lần; chảy máu chân răng nhẹ, không phân đen."},{"question":"Có lừ đừ, vật vã, chân tay lạnh, tiểu ít không?","response":"Mệt lả, chóng mặt khi ngồi dậy, tiểu ít hơn bình thường."},{"question":"Yếu tố dịch tễ: ở vùng có dịch, người xung quanh có sốt xuất huyết, bị muỗi đốt không?","response":"Đồng nghiệp cùng phòng trọ vừa nhập viện vì sốt xuất huyết; khu trọ có nhiều lăng quăng."},{"question":"Đã dùng thuốc hạ sốt gì, có dùng aspirin hoặc kháng viêm không?","response":"Chỉ dùng paracetamol, không dùng aspirin, ibuprofen."},{"question":"Có ho, đau họng, tiêu chảy, phát ban không?","response":"Không ho, không tiêu chảy; chưa phát ban."},{"question":"Có bệnh nền như đái tháo đường, tim mạch, béo phì không?","response":"Không."}],"examination":[{"group":"K","item":"Tuần hoàn","finding":"Mạch 104 lần/phút nhẹ, huyết áp 100/74 mmHg (hiệu áp 26 mmHg), đầu chi mát, thời gian làm đầy mao mạch 3 giây."},{"group":"K","item":"Da niêm mạc","finding":"Da hồng, có vài chấm xuất huyết dưới da cẳng chân; nghiệm pháp dây thắt dương tính; chảy máu chân răng nhẹ."},{"group":"K","item":"Bụng","finding":"Ấn đau hạ sườn phải, gan to 2 cm dưới bờ sườn, mềm; không báng bụng rõ."},{"group":"K","item":"Phổi","finding":"Rì rào phế nang giảm nhẹ đáy phải, gõ đục nhẹ, gợi ý tràn dịch màng phổi ít."},{"group":"K","item":"Tri giác","finding":"Tỉnh, trả lời đúng, hơi mệt."}],"investigations":[{"name":"Công thức máu và hematocrit","duration_minutes":10,"result":"Hematocrit 48% (nền khoảng 41%); tiểu cầu 42 G/L; bạch cầu 3,2 G/L."},{"name":"Test nhanh NS1 và IgM, IgG Dengue","duration_minutes":10,"result":"NS1 dương tính; IgM âm tính, IgG âm tính (nhiễm tiên phát)."},{"name":"AST, ALT, albumin, điện giải","duration_minutes":10,"result":"AST 196 U/L; ALT 142 U/L; albumin 33 g/L; Na 134 mmol/L."},{"name":"Siêu âm bụng và màng phổi","duration_minutes":15,"result":"Dày thành túi mật 5 mm, dịch quanh túi mật; ít dịch màng phổi phải."},{"name":"Cấy máu và CRP","duration_minutes":10,"result":"CRP 14 mg/L; cấy máu chờ kết quả."},{"name":"Truyền tiểu cầu dự phòng vì tiểu cầu dưới 50 G/L khi không xuất huyết nặng","duration_minutes":10,"result":"Không có chỉ định; có thể gây quá tải dịch và không cải thiện kết cục."}],"choices":{"diagnosis":{"ydx":["Nhiễm khuẩn huyết do vi khuẩn Gram âm","Viêm gan virus A cấp","Sốt rét do Plasmodium falciparum","Sốt xuất huyết Dengue có dấu hiệu cảnh báo, giai đoạn nguy hiểm"]},"actions":["Nhập viện theo dõi, đặt đường truyền, bắt đầu truyền dịch tinh thể theo phác đồ có dấu hiệu cảnh báo","Truyền tiểu cầu dự phòng và tiêm bắp thuốc giảm đau","Chuẩn bị xử trí sốc: dịch tinh thể nhanh, đánh giá lại, cân nhắc chất keo khi sốc nặng","Theo dõi sát mạch, huyết áp, hiệu áp, nước tiểu, hematocrit, tiểu cầu mỗi 1 đến 2 giờ","Dùng paracetamol hạ sốt, tránh aspirin và kháng viêm không steroid","Siêu âm bụng và màng phổi để đánh giá thoát huyết tương"]}}'::jsonb,
  '3071f993a78a7ec1fb1526230dc8f53e8962429dbbdb350018d3d4c5329d7e4b'
)
on conflict (case_id) do update set
