values (
  'noi-nhiem-001',
  '{"schema_version":"1.0.0","case_id":"noi-nhiem-001","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-nhiem-001-1","resource_type":"other","source":"World Health Organization. Dengue: guidelines for diagnosis, treatment, prevention and control (new edition 2009) và cập nhật WHO 2012 Handbook for clinical management of dengue.","title":"World Health Organization. Dengue: guidelines for diagnosis, treatment, prevention and control (new edition 2009) và cập nhật WHO 2012 Handbook for clinical management of dengue.","organization":null,"year_version":null,"citation":"World Health Organization. Dengue: guidelines for diagnosis, treatment, prevention and control (new edition 2009) và cập nhật WHO 2012 Handbook for clinical management of dengue.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-3705-2019","resource_type":"regulation","source":"https://caselaw.vn/van-ban-phap-luat/331396-quyet-dinh-so-3705-qd-byt-ngay-22-08-2019-ve-huong-dan-chan-doan-dieu-tri-sot-xuat-huyet-dengue","title":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị sốt xuất huyết Dengue (Quyết định 3705/QĐ-BYT, 2019 và cập nhật).","organization":null,"year_version":null,"citation":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị sốt xuất huyết Dengue (Quyết định 3705/QĐ-BYT, 2019 và cập nhật).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-nhiem-001-3","resource_type":"textbook","source":"Giáo trình Bệnh truyền nhiễm, các trường đại học Y Việt Nam.","title":"Giáo trình Bệnh truyền nhiễm, các trường đại học Y Việt Nam.","organization":null,"year_version":null,"citation":"Giáo trình Bệnh truyền nhiễm, các trường đại học Y Việt Nam.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm gan virus A cấp","credit":"none"},{"text":"Sốt xuất huyết Dengue có dấu hiệu cảnh báo, giai đoạn nguy hiểm","credit":"full"},{"text":"Sốt rét do Plasmodium falciparum","credit":"none"},{"text":"Nhiễm khuẩn huyết do vi khuẩn Gram âm","credit":"none"}]},"action_options":[{"text":"Nhập viện theo dõi, đặt đường truyền, bắt đầu truyền dịch tinh thể theo phác đồ có dấu hiệu cảnh báo","time_minutes":2,"grade":"critical","rationale":"Đau bụng, gan to, hematocrit tăng và tiểu cầu giảm là dấu hiệu cảnh báo, cần bù dịch sớm có kiểm soát."},{"text":"Theo dõi sát mạch, huyết áp, hiệu áp, nước tiểu, hematocrit, tiểu cầu mỗi 1 đến 2 giờ","time_minutes":2,"grade":"critical","rationale":"Giai đoạn nguy hiểm dễ sốc do thoát huyết tương."},{"text":"Dùng paracetamol hạ sốt, tránh aspirin và kháng viêm không steroid","time_minutes":2,"grade":"recommended","rationale":"Tránh tăng nguy cơ xuất huyết và độc gan."},{"text":"Siêu âm bụng và màng phổi để đánh giá thoát huyết tương","time_minutes":2,"grade":"recommended","rationale":"Dày thành túi mật, dịch màng phổi hỗ trợ chẩn đoán."},{"text":"Chuẩn bị xử trí sốc: dịch tinh thể nhanh, đánh giá lại, cân nhắc chất keo khi sốc nặng","time_minutes":2,"grade":"recommended","rationale":"Hiệu áp kẹt và đầu chi mát cảnh báo sốc sắp xảy ra."},{"text":"Truyền tiểu cầu dự phòng và tiêm bắp thuốc giảm đau","time_minutes":0,"grade":"harmful","rationale":"Tiêm bắp gây tụ máu, truyền tiểu cầu không có chỉ định, làm quá tải dịch."}],"teaching_explanation":"Sốt xuất huyết Dengue diễn tiến qua ba giai đoạn: sốt, nguy hiểm, hồi phục. Dấu hiệu cảnh báo ở thời điểm hết sốt (đau bụng, nôn, gan to, hematocrit tăng kèm tiểu cầu giảm) đòi hỏi nhập viện, truyền dịch tinh thể có kiểm soát và theo dõi sát."}'::jsonb,
  'd1985e4b38bbafaa81141387b2a8219ea0bce59d3d59df70cf3c42166a2c68c6'
)
