insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-nhiem-002',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-nhiem-002","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Sốt cao, đau đầu dữ dội và cứng gáy","setting":"giuong","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":46,"sex":"nữ","patient_label":"Người bệnh mô phỏng N20"},"presentation":{"intro":"Người bệnh nữ 46 tuổi nhập cấp cứu vì sốt cao 2 ngày, đau đầu dữ dội, nôn và cứng gáy sau đợt viêm tai giữa.","place":null,"clock":null,"night":false},"vitals":{"hr":112,"sbp":104,"dbp":62,"rr":24,"temperature_c":39.8,"spo2":96},"history":[{"question":"Triệu chứng khởi phát và diễn tiến thế nào?","response":"Sốt cao rét run 2 ngày, đau đầu dữ dội tăng dần, nôn vọt, sợ ánh sáng; sáng nay lơ mơ."},{"question":"Có viêm tai, viêm xoang, chấn thương đầu hoặc phẫu thuật thần kinh gần đây không?","response":"Đau tai phải, chảy mủ tai một tuần, chưa điều trị; không chấn thương đầu."},{"question":"Có co giật, yếu liệt, nói khó không?","response":"Không co giật, không yếu liệt, nói chậm hơn."},{"question":"Có phát ban, chấm xuất huyết da không?","response":"Không có."},{"question":"Tiền sử bệnh nền, suy giảm miễn dịch, cắt lách, nghiện rượu, tiêm phòng?","response":"Khỏe mạnh, không bệnh nền; chưa tiêm phòng phế cầu."},{"question":"Có dị ứng thuốc, nhất là kháng sinh không?","response":"Không."},{"question":"Có tiếp xúc người bị viêm màng não hoặc đi vùng dịch không?","response":"Không."}],"examination":[{"group":"K","item":"Tri giác","finding":"GCS 13 (E3 V4 M6), lơ mơ, trả lời chậm, không dấu thần kinh khu trú."},{"group":"K","item":"Dấu màng não","finding":"Cứng gáy rõ, dấu Kernig và Brudzinski dương tính."},{"group":"K","item":"Đáy mắt và đồng tử","finding":"Đồng tử hai bên đều, phản xạ ánh sáng tốt; không phù gai thị."},{"group":"K","item":"Tai mũi họng","finding":"Tai phải chảy mủ, màng nhĩ thủng, ấn xương chũm đau."},{"group":"K","item":"Da","finding":"Không ban, không xuất huyết da."}],"investigations":[{"name":"Cấy máu hai bộ và công thức máu, CRP, đường huyết, điện giải","duration_minutes":10,"result":"Bạch cầu 21,6 G/L (đa nhân 92%); CRP 245 mg/L; glucose máu 6,4 mmol/L; Na 133 mmol/L."},{"name":"Chọc dò dịch não tủy: áp lực, tế bào, protein, glucose, Gram, cấy","duration_minutes":10,"result":"Áp lực mở 32 cmH2O; đục; bạch cầu 2800/mm3 (đa nhân 90%); protein 3,6 g/L; glucose 1,0 mmol/L (tỷ lệ với máu 0,16); Gram thấy cầu khuẩn Gram dương xếp đôi."},{"name":"CT sọ não có cản quang","duration_minutes":40,"result":"Không khối choán chỗ, không thoát vị; dày màng não, mờ xương chũm phải."},{"name":"Procalcitonin hoặc lactate máu","duration_minutes":10,"result":"Lactate 3,0 mmol/L; procalcitonin tăng cao."},{"name":"Chọc dò dịch não tủy bắt buộc sau khi chờ kết quả CT, hoãn kháng sinh đến khi có Gram","duration_minutes":40,"result":"Không được hoãn kháng sinh quá 1 giờ khi nghi ngờ cao viêm màng não mủ."}],"choices":{"diagnosis":{"ydx":["Viêm màng não do virus","Viêm màng não do lao","Xuất huyết dưới nhện","Viêm màng não mủ do cầu khuẩn phế cầu, biến chứng từ viêm tai giữa mạn"]},"actions":["Chọc dò dịch não tủy khi không có chống chỉ định (không dấu thần kinh khu trú, không phù gai, không rối loạn đông máu) hoặc sau CT","Dùng dexamethasone cùng liều kháng sinh đầu tiên","Chỉ dùng paracetamol, cho thuốc an thần và theo dõi tại nhà","Theo dõi thần kinh, co giật, natri, chống phù não và bù dịch hợp lý","Lấy cấy máu rồi dùng ngay kháng sinh tĩnh mạch (ceftriaxone phối hợp vancomycin), không chờ kết quả chọc dò nếu phải trì hoãn","Hội chẩn tai mũi họng về viêm tai giữa, viêm xương chũm"]}}'::jsonb,
  'c7fec17d732bfcfa16c41862c817eab33f9b9537eeb88a5bf9067b99710fc9c0'
)
