insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-nhiem-002',
  '{"schema_version":"1.0.0","case_id":"noi-nhiem-002","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-meningitis-escmid-2016","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/27062097/","title":"van de Beek D, et al. ESCMID guideline: diagnosis and treatment of acute bacterial meningitis. Clin Microbiol Infect 2016;22 Suppl 3:S37-62.","organization":null,"year_version":null,"citation":"van de Beek D, et al. ESCMID guideline: diagnosis and treatment of acute bacterial meningitis. Clin Microbiol Infect 2016;22 Suppl 3:S37-62.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-meningitis-idsa-2004","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/15494903/","title":"Tunkel AR, et al. Practice guidelines for the management of bacterial meningitis. IDSA. Clin Infect Dis 2004;39:1267-84.","organization":null,"year_version":null,"citation":"Tunkel AR, et al. Practice guidelines for the management of bacterial meningitis. IDSA. Clin Infect Dis 2004;39:1267-84.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-4132-2018","resource_type":"other","source":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị viêm màng não mủ (Quyết định 4132/QĐ-BYT, 2018 hoặc bản hiện hành, cần đối chiếu).","title":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị viêm màng não mủ (Quyết định 4132/QĐ-BYT, 2018 hoặc bản hiện hành, cần đối chiếu).","organization":null,"year_version":null,"citation":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị viêm màng não mủ (Quyết định 4132/QĐ-BYT, 2018 hoặc bản hiện hành, cần đối chiếu).","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-nhiem-002-4","resource_type":"textbook","source":"Giáo trình Bệnh truyền nhiễm, các trường đại học Y Việt Nam.","title":"Giáo trình Bệnh truyền nhiễm, các trường đại học Y Việt Nam.","organization":null,"year_version":null,"citation":"Giáo trình Bệnh truyền nhiễm, các trường đại học Y Việt Nam.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm màng não do virus","credit":"none"},{"text":"Xuất huyết dưới nhện","credit":"none"},{"text":"Viêm màng não mủ do cầu khuẩn phế cầu, biến chứng từ viêm tai giữa mạn","credit":"full"},{"text":"Viêm màng não do lao","credit":"none"}]},"action_options":[{"text":"Lấy cấy máu rồi dùng ngay kháng sinh tĩnh mạch (ceftriaxone phối hợp vancomycin), không chờ kết quả chọc dò nếu phải trì hoãn","time_minutes":2,"grade":"critical","rationale":"Viêm màng não mủ là cấp cứu; trì hoãn kháng sinh làm tăng tử vong và di chứng."},{"text":"Dùng dexamethasone cùng liều kháng sinh đầu tiên","time_minutes":2,"grade":"critical","rationale":"Giảm viêm và di chứng thần kinh, mất thính lực, đặc biệt trong viêm màng não phế cầu."},{"text":"Chọc dò dịch não tủy khi không có chống chỉ định (không dấu thần kinh khu trú, không phù gai, không rối loạn đông máu) hoặc sau CT","time_minutes":2,"grade":"recommended","rationale":"Cung cấp chẩn đoán và hướng dẫn kháng sinh."},{"text":"Hội chẩn tai mũi họng về viêm tai giữa, viêm xương chũm","time_minutes":2,"grade":"recommended","rationale":"Nguồn nhiễm cần kiểm soát bằng phẫu thuật nếu cần."},{"text":"Theo dõi thần kinh, co giật, natri, chống phù não và bù dịch hợp lý","time_minutes":2,"grade":"recommended","rationale":"Có nguy cơ tăng áp lực nội sọ, hạ natri do SIADH, co giật."},{"text":"Chỉ dùng paracetamol, cho thuốc an thần và theo dõi tại nhà","time_minutes":0,"grade":"harmful","rationale":"Bỏ sót cấp cứu, đe dọa tính mạng."}],"teaching_explanation":"Viêm màng não mủ cần dùng kháng sinh trong vòng 1 giờ sau khi nghi ngờ, kèm dexamethasone. Nếu không có dấu hiệu thoát vị hoặc chống chỉ định, chọc dò dịch não tủy; kết quả điển hình: đục, bạch cầu đa nhân tăng, protein tăng, glucose giảm."}'::jsonb,
  'b6a6f5c51d490793ac75ecbe49bb178b200dd44c3931c733dd9dda633c1b7cfb'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-bung-001',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-bung-001","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau bụng chuyển xuống hố chậu phải","setting":"giuong","level":"Dễ","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":24,"sex":"nam","patient_label":"Người bệnh mô phỏng B. V. T."},"presentation":{"intro":"Nam thanh niên đến khám vì đau bụng từ quanh rốn chuyển xuống hố chậu phải 18 giờ, kèm sốt nhẹ và nôn.","place":null,"clock":null,"night":false},"vitals":{"hr":98,"sbp":120,"dbp":75,"rr":20,"temperature_c":38.1,"spo2":99},"history":[{"question":"Đau bụng bắt đầu từ đâu, diễn tiến thế nào?","response":"Đau âm ỉ quanh rốn từ tối qua, khoảng 8 giờ sau khu trú dần xuống hố chậu phải, đau tăng khi ho hoặc đi lại."},{"question":"Có buồn nôn, nôn hoặc chán ăn không?","response":"Chán ăn từ tối qua, buồn nôn, nôn hai lần ra thức ăn, nôn xong đau không giảm."},{"question":"Có sốt, rối loạn đại tiện hoặc tiểu buốt không?","response":"Sốt nhẹ khoảng 38 độ, đi cầu phân sệt một lần, không tiểu buốt, không tiểu máu."},{"question":"Có tiền sử mổ bụng, bệnh dạ dày hoặc sỏi tiết niệu không?","response":"Chưa từng mổ, không loét dạ dày, không đau quặn thận trước đây."},{"question":"Lần ăn cuối và có dùng thuốc giảm đau không?","response":"Ăn cơm trưa hôm qua; chưa dùng thuốc giảm đau, chưa dùng kháng sinh."},{"question":"Có dị ứng thuốc không?","response":"Không dị ứng thuốc, thức ăn."},{"question":"Có ho, khó thở hoặc người nhà bị tiêu chảy cùng lúc không?","response":"Không ho, không khó thở, không ai trong nhà tiêu chảy."}],"examination":[{"group":"K","item":"Khám bụng: ấn đau và phản ứng thành bụng","finding":"Ấn đau khu trú hố chậu phải ở điểm McBurney, có co cứng nhẹ thành bụng và phản ứng dội (+)."},{"group":"K","item":"Các dấu hiệu gián tiếp","finding":"Dấu Rovsing (+), dấu cơ thắt lưng chậu (+) nhẹ."},{"group":"K","item":"Toàn trạng và dấu hiệu sinh tồn","finding":"Tỉnh, vẻ mặt đau, môi khô nhẹ, mạch 98 lần/phút, nhiệt độ 38,1 độ C."},{"group":"K","item":"Thăm trực tràng","finding":"Ấn đau thành phải trực tràng, không có khối, găng không dính máu."},{"group":"K","item":"Tim và phổi","finding":"Tim đều, phổi thông khí rõ, không ran."},{"group":"K","item":"Bìu và vùng bẹn","finding":"Hai tinh hoàn bình thường, không đau, không khối thoát vị."}],"investigations":[{"name":"Công thức máu và CRP","duration_minutes":10,"result":"Bạch cầu 14,2 G/L, bạch cầu đa nhân trung tính 84%; CRP 62 mg/L."},{"name":"Siêu âm bụng bằng đầu dò ép từng lớp","duration_minutes":15,"result":"Ruột thừa đường kính 9 mm, không xẹp khi ép, thành dày, có ít dịch quanh ruột thừa; thận và đường mật bình thường."},{"name":"Tổng phân tích nước tiểu","duration_minutes":10,"result":"Không hồng cầu, bạch cầu hay nitrit."},{"name":"Điện giải đồ và creatinin","duration_minutes":10,"result":"Na 137, K 3,8 mmol/L; creatinin 82 µmol/L."},{"name":"Chụp CT bụng có thuốc cản quang ngay cho mọi người trẻ không có chỉ định đặc biệt","duration_minutes":40,"result":"Không cần thiết khi lâm sàng và siêu âm đã rõ; tăng phơi nhiễm bức xạ."},{"name":"Chụp X quang bụng đứng thường quy tìm nguyên nhân","duration_minutes":10,"result":"Không có giá trị định hướng, không thay đổi xử trí."}],"choices":{"diagnosis":{"ydx":["Sỏi niệu quản phải","Viêm dạ dày ruột cấp","Viêm hạch mạc treo ruột","Viêm ruột thừa cấp chưa biến chứng"]},"actions":["Cho uống thuốc nhuận tràng, chườm nóng và về nhà theo dõi","Hội chẩn ngoại khoa và chuẩn bị mổ sớm","Giảm đau đường tĩnh mạch, không che lấp dấu hiệu khám","Kháng sinh trước mổ một liều phù hợp, ví dụ cephalosporin phối hợp metronidazol","Chụp X quang bụng đứng thường quy","Nhịn ăn uống, đặt đường truyền, bù dịch tinh thể","Cho thuốc nhuận tràng để làm sạch ruột"]}}'::jsonb,
  '73fe6e520b51b9b106d16affa28b6ace4e9a7f806c608a3b8818a5f05edebb5e'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
