values (
  'ngoai-bung-001',
  '{"schema_version":"1.0.0","case_id":"ngoai-bung-001","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-appendicitis-wses-2020-5b10185705b5","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/32295644/","title":"Di Saverio S et al. Diagnosis and treatment of acute appendicitis: 2020 update of the WSES Jerusalem guidelines. World J Emerg Surg 2020.","organization":null,"year_version":null,"citation":"Di Saverio S et al. Diagnosis and treatment of acute appendicitis: 2020 update of the WSES Jerusalem guidelines. World J Emerg Surg 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-bung-001-2","resource_type":"textbook","source":"Giáo trình Bệnh học Ngoại khoa, Đại học Y Hà Nội, phần Cấp cứu bụng - Viêm ruột thừa cấp.","title":"Giáo trình Bệnh học Ngoại khoa, Đại học Y Hà Nội, phần Cấp cứu bụng - Viêm ruột thừa cấp.","organization":null,"year_version":null,"citation":"Giáo trình Bệnh học Ngoại khoa, Đại học Y Hà Nội, phần Cấp cứu bụng - Viêm ruột thừa cấp.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-bung-001-3","resource_type":"textbook","source":"Townsend CM et al. Sabiston Textbook of Surgery, 21st edition, 2022, chương Appendix.","title":"Townsend CM et al. Sabiston Textbook of Surgery, 21st edition, 2022, chương Appendix.","organization":null,"year_version":null,"citation":"Townsend CM et al. Sabiston Textbook of Surgery, 21st edition, 2022, chương Appendix.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,5],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm hạch mạc treo ruột","credit":"none"},{"text":"Sỏi niệu quản phải","credit":"none"},{"text":"Viêm ruột thừa cấp chưa biến chứng","credit":"full"},{"text":"Viêm dạ dày ruột cấp","credit":"none"}]},"action_options":[{"text":"Nhịn ăn uống, đặt đường truyền, bù dịch tinh thể","time_minutes":2,"grade":"critical","rationale":"Người bệnh nôn, môi khô, cần bù dịch trước mổ."},{"text":"Hội chẩn ngoại khoa và chuẩn bị mổ sớm","time_minutes":2,"grade":"critical","rationale":"Chẩn đoán đã rõ, mổ sớm giảm nguy cơ vỡ ruột thừa."},{"text":"Kháng sinh trước mổ một liều phù hợp, ví dụ cephalosporin phối hợp metronidazol","time_minutes":2,"grade":"recommended","rationale":"Giảm nhiễm trùng vết mổ và áp xe tồn dư."},{"text":"Giảm đau đường tĩnh mạch, không che lấp dấu hiệu khám","time_minutes":1,"grade":"recommended","rationale":"Giảm đau không làm sai lệch chẩn đoán khi đã khám kỹ."},{"text":"Chụp X quang bụng đứng thường quy","time_minutes":1,"grade":"waste","rationale":"Không giúp xác định chẩn đoán và không thay đổi hướng xử trí."},{"text":"Cho thuốc nhuận tràng để làm sạch ruột","time_minutes":0,"grade":"waste","rationale":"Không có chỉ định, có thể làm tăng nguy cơ vỡ."},{"text":"Cho uống thuốc nhuận tràng, chườm nóng và về nhà theo dõi","time_minutes":0,"grade":"harmful","rationale":"Chườm nóng và nhuận tràng làm tăng nguy cơ vỡ ruột thừa."}],"teaching_explanation":"Đau chuyển từ quanh rốn xuống hố chậu phải kèm chán ăn, nôn, sốt nhẹ, bạch cầu tăng gợi viêm ruột thừa; điểm Alvarado 10 điểm. Siêu âm đủ để quyết định ở người trẻ, mổ sớm trước khi vỡ."}'::jsonb,
