insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-bung-002',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-bung-002","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau quặn bụng, nôn và bí trung đại tiện sau mổ cũ","setting":"giuong","level":"Trung bình","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":58,"sex":"nữ","patient_label":"Người bệnh mô phỏng N. T. L."},"presentation":{"intro":"Nữ 58 tuổi từng mổ cắt tử cung đường bụng, nhập viện vì đau quặn bụng, nôn và không đánh hơi, không đi cầu 2 ngày.","place":null,"clock":null,"night":false},"vitals":{"hr":104,"sbp":105,"dbp":65,"rr":20,"temperature_c":37.4,"spo2":98},"history":[{"question":"Đau bụng có tính chất gì, có từng cơn không?","response":"Đau quặn từng cơn quanh rốn, mỗi cơn vài phút, xen kẽ lúc dịu; hai ngày nay tăng dần."},{"question":"Có nôn không, nôn ra gì?","response":"Nôn nhiều lần, ban đầu thức ăn, sau chuyển dịch vàng xanh, nôn xong dễ chịu hơn một chút."},{"question":"Có đánh hơi và đi cầu được không?","response":"Không trung tiện, không đi cầu từ hai ngày nay."},{"question":"Có tiền sử phẫu thuật bụng hoặc xạ trị vùng chậu không?","response":"Mổ cắt tử cung toàn phần đường bụng cách đây 10 năm do u xơ; không xạ trị."},{"question":"Từng có đợt tương tự trước đây không?","response":"Một lần cách đây 3 năm, tự hết sau nhịn ăn 1 ngày ở tuyến dưới."},{"question":"Có sút cân, đi cầu phân máu hoặc thay đổi thói quen đại tiện kéo dài không?","response":"Không sút cân, không phân máu, trước đó đi cầu bình thường."},{"question":"Có dùng thuốc nhuận tràng, thuốc opioid hoặc bệnh tuyến giáp, đái tháo đường không?","response":"Không dùng opioid, không bệnh nội khoa nền."}],"examination":[{"group":"K","item":"Khám bụng: nhìn, sờ","finding":"Bụng chướng vừa, sẹo mổ đường giữa dưới rốn cũ; ấn đau lan tỏa nhẹ, không co cứng, không phản ứng dội."},{"group":"K","item":"Nghe nhu động ruột","finding":"Nhu động ruột tăng, âm sắc cao, có tiếng nước óc ách."},{"group":"K","item":"Khám vùng bẹn, đùi và sẹo mổ","finding":"Không có khối thoát vị bẹn, đùi, thành bụng."},{"group":"K","item":"Thăm trực tràng","finding":"Bóng trực tràng rỗng, không khối, găng không dính máu."},{"group":"K","item":"Dấu hiệu mất nước","finding":"Môi khô, niêm mạc khô, da nhăn nhẹ, tiểu ít."},{"group":"K","item":"Tim phổi","finding":"Tim nhanh đều, phổi trong."}],"investigations":[{"name":"X quang bụng đứng không chuẩn bị","duration_minutes":10,"result":"Nhiều mức nước hơi hình bậc thang ở vùng giữa bụng, quai ruột non giãn, ít hơi ở đại tràng."},{"name":"CT bụng có thuốc cản quang","duration_minutes":40,"result":"Ruột non giãn 3,3 cm trên đoạn gần, có điểm chuyển tiếp từ giãn sang xẹp ở hố chậu phải theo dải dính, đoạn xa xẹp; thành ruột ngấm thuốc đều, ít dịch tự do, không khí trong thành ruột."},{"name":"Công thức máu, điện giải, creatinin, lactate","duration_minutes":10,"result":"Bạch cầu 11,2 G/L; Na 134, K 3,2 mmol/L; creatinin 108 µmol/L; lactate 1,6 mmol/L."},{"name":"Đường huyết và khí máu","duration_minutes":10,"result":"Đường huyết 6,1 mmol/L; pH 7,41, HCO3 24 mmol/L."},{"name":"Nội soi đại tràng ngay lập tức","duration_minutes":20,"result":"Không có chỉ định cấp cứu khi chưa nghi nguyên nhân đại tràng, nguy cơ thủng."},{"name":"Cho uống thuốc cản quang bari để chụp ruột","duration_minutes":10,"result":"Chống chỉ định trong tắc ruột có thể mổ, nguy cơ tắc hoàn toàn và viêm phúc mạc bari."}],"choices":{"diagnosis":{"ydx":["Viêm tụy cấp","Liệt ruột cơ năng sau viêm phúc mạc","Tắc ruột do khối u đại tràng","Tắc ruột non do dính sau mổ, chưa có dấu hiệu nghẹt"]},"actions":["Cho thụt tháo và thuốc nhuận tràng mạnh","Khám lại bụng mỗi 4 đến 6 giờ, theo dõi mạch, nhiệt độ, lactate và lượng dịch dẫn lưu","Nhịn ăn uống, đặt đường truyền và bù dịch Ringer lactat","Đặt sonde dạ dày hút dịch giảm áp","Bù kali và theo dõi điện giải mỗi 12 giờ","Cân nhắc thuốc cản quang tan trong nước đường uống có đánh giá sau 24 giờ","Cho uống thuốc cản quang bari"]}}'::jsonb,
  '85449c9b74f559a8241fe9918c40e74c975a498ae1e976ab6cb0f7e49e1ed981'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
