insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'ngoai-bung-002',
  '{"schema_version":"1.0.0","case_id":"ngoai-bung-002","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-asbo-bologna-2017-5e6d01e592df","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/29946347/","title":"Ten Broek RPG et al. Bologna guidelines for diagnosis and management of adhesive small bowel obstruction (ASBO): 2017 update of the evidence-based guidelines from the WSES ASBO working group. World J Emerg Surg 2018;13:24.","organization":null,"year_version":null,"citation":"Ten Broek RPG et al. Bologna guidelines for diagnosis and management of adhesive small bowel obstruction (ASBO): 2017 update of the evidence-based guidelines from the WSES ASBO working group. World J Emerg Surg 2018;13:24.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-bung-002-2","resource_type":"textbook","source":"Giáo trình Bệnh học Ngoại khoa, Đại học Y Hà Nội, bài Tắc ruột.","title":"Giáo trình Bệnh học Ngoại khoa, Đại học Y Hà Nội, bài Tắc ruột.","organization":null,"year_version":null,"citation":"Giáo trình Bệnh học Ngoại khoa, Đại học Y Hà Nội, bài Tắc ruột.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-bung-002-3","resource_type":"textbook","source":"Townsend CM et al. Sabiston Textbook of Surgery, 21st edition, 2022, chương Small Intestine.","title":"Townsend CM et al. Sabiston Textbook of Surgery, 21st edition, 2022, chương Small Intestine.","organization":null,"year_version":null,"citation":"Townsend CM et al. Sabiston Textbook of Surgery, 21st edition, 2022, chương Small Intestine.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Liệt ruột cơ năng sau viêm phúc mạc","credit":"none"},{"text":"Tắc ruột do khối u đại tràng","credit":"none"},{"text":"Tắc ruột non do dính sau mổ, chưa có dấu hiệu nghẹt","credit":"full"},{"text":"Viêm tụy cấp","credit":"none"}]},"action_options":[{"text":"Nhịn ăn uống, đặt đường truyền và bù dịch Ringer lactat","time_minutes":2,"grade":"critical","rationale":"Người bệnh mất nước và hạ kali, cần bù dịch ngay."},{"text":"Đặt sonde dạ dày hút dịch giảm áp","time_minutes":2,"grade":"critical","rationale":"Giảm chướng, giảm nôn, giảm nguy cơ hít sặc."},{"text":"Bù kali và theo dõi điện giải mỗi 12 giờ","time_minutes":2,"grade":"recommended","rationale":"Hạ kali 3,2 làm nặng liệt ruột và loạn nhịp."},{"text":"Khám lại bụng mỗi 4 đến 6 giờ, theo dõi mạch, nhiệt độ, lactate và lượng dịch dẫn lưu","time_minutes":2,"grade":"recommended","rationale":"Phát hiện sớm dấu hiệu nghẹt hoặc thủng."},{"text":"Cân nhắc thuốc cản quang tan trong nước đường uống có đánh giá sau 24 giờ","time_minutes":2,"grade":"recommended","rationale":"Vừa tiên lượng vừa có thể điều trị tắc bán phần."},{"text":"Cho thụt tháo và thuốc nhuận tràng mạnh","time_minutes":0,"grade":"waste","rationale":"Không hiệu quả trong tắc cơ học ruột non."},{"text":"Cho uống thuốc cản quang bari","time_minutes":0,"grade":"harmful","rationale":"Nguy cơ tắc hoàn toàn và viêm phúc mạc do bari nếu thủng."}],"teaching_explanation":"Tiền sử mổ bụng, đau quặn từng cơn, nôn, bí trung đại tiện, chướng bụng là bộ khung của tắc ruột cơ học; dính sau mổ là nguyên nhân thường gặp nhất. Cần phân biệt tắc đơn thuần với nghẹt để quyết định mổ sớm hay điều trị bảo tồn có kiểm soát."}'::jsonb,
  '2c52654cc9fbfb50faa5d60c2efaede80093099d9bd5367d3f1ca845649675ef'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-bung-003',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-bung-003","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Khối phồng vùng bẹn không đẩy lên được, đau và nôn","setting":"capcuu","level":"Trung bình","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":67,"sex":"nam","patient_label":"Người bệnh mô phỏng H. V. C."},"presentation":{"intro":"Nam 67 tuổi có khối phồng bẹn phải 5 năm, 10 giờ nay khối căng đau, không đẩy lên được, nôn nhiều lần.","place":null,"clock":null,"night":false},"vitals":{"hr":100,"sbp":130,"dbp":80,"rr":20,"temperature_c":37.8,"spo2":97},"history":[{"question":"Khối phồng ở bẹn có từ bao giờ, thường ra sao?","response":"Khối bẹn phải 5 năm, đứng hoặc gắng sức thì to, nằm thì tự xẹp."},{"question":"Lần này khối có đẩy lên được không?","response":"Từ 10 giờ nay khối không tự xẹp, tự đẩy cũng không được, căng và đau tăng dần."},{"question":"Có nôn, bí trung đại tiện hoặc chướng bụng không?","response":"Nôn 3 lần, trung tiện được ít, bụng hơi chướng, chưa đi cầu từ sáng."},{"question":"Có yếu tố làm tăng áp lực ổ bụng không?","response":"Táo bón kéo dài, tiểu khó vì phì đại tuyến tiền liệt, ho mạn do hút thuốc."},{"question":"Có sốt, da vùng khối thay đổi không?","response":"Sốt nhẹ, da trên khối hơi đỏ, nóng."},{"question":"Có tiền sử mổ vùng bẹn hoặc bệnh tim phổi không?","response":"Chưa mổ bẹn; tăng huyết áp dùng amlodipin; hút thuốc 30 gói-năm."},{"question":"Có dùng thuốc chống đông hoặc dị ứng thuốc không?","response":"Không dùng chống đông, không dị ứng."}],"examination":[{"group":"K","item":"Khám khối vùng bẹn bìu phải","finding":"Khối bẹn bìu phải kích thước 6 x 5 cm, căng, chắc, rất đau, da trên khối đỏ nhẹ, không đẩy lên được, ho không có xung động."},{"group":"K","item":"Khám bụng","finding":"Bụng chướng nhẹ, ấn đau nhẹ quanh rốn, không co cứng; nhu động ruột tăng."},{"group":"K","item":"Khám bên đối diện và tinh hoàn","finding":"Bẹn trái bình thường; tinh hoàn phải sờ được riêng, không đau, ở phía dưới khối."},{"group":"K","item":"Thăm trực tràng, tiền liệt tuyến","finding":"Tiền liệt tuyến to đều, không đau; bóng trực tràng có ít phân."},{"group":"K","item":"Tim phổi","finding":"Tim đều, phổi ran ngáy nhẹ."},{"group":"K","item":"Dấu hiệu mất nước","finding":"Niêm mạc hơi khô."}],"investigations":[{"name":"Công thức máu, CRP và lactate","duration_minutes":10,"result":"Bạch cầu 13,5 G/L; CRP 48 mg/L; lactate 2,4 mmol/L."},{"name":"Siêu âm vùng bẹn bìu có Doppler","duration_minutes":15,"result":"Quai ruột trong túi thoát vị, thành dày, nhu động giảm, ít dịch quanh quai; tinh hoàn tưới máu bình thường."},{"name":"X quang bụng đứng","duration_minutes":10,"result":"Vài mức nước hơi ruột non, hơi đại tràng ít."},{"name":"Điện giải đồ, creatinin, điện tâm đồ","duration_minutes":10,"result":"Na 136, K 3,6 mmol/L; creatinin 98 µmol/L; điện tâm đồ nhịp xoang 100 lần/phút."},{"name":"Chụp CT bụng chậu có cản quang cho mọi trường hợp trước khi mổ dù chẩn đoán đã rõ","duration_minutes":40,"result":"Không thay đổi chỉ định mổ cấp cứu và làm chậm trễ."},{"name":"Cố gắng đẩy khối nhiều lần tại phòng khám để thoát vị lên","duration_minutes":10,"result":"Nguy cơ đẩy ruột hoại tử vào ổ bụng, bỏ sót thủng."}],"choices":{"diagnosis":{"ydx":["Tràn dịch màng tinh hoàn","Thoát vị bẹn gián tiếp bên phải bị nghẹt","Viêm mào tinh hoàn cấp","Xoắn thừng tinh"]},"actions":["Nhịn ăn, đặt đường truyền, bù dịch tinh thể","Hội chẩn ngoại khoa và chuẩn bị mổ cấp cứu","Đẩy khối tại chỗ vài lần trong khi chờ siêu âm","Cố đẩy khối thoát vị bằng lực mạnh và cho về nhà","Đánh giá lại tim phổi, đường huyết và chuẩn bị gây mê","Kháng sinh dự phòng trước mổ (cephalosporin), giảm đau tĩnh mạch","Đặt sonde dạ dày hút khi nôn nhiều hoặc chướng bụng"]}}'::jsonb,
  '361f68d4a6d73512da91da23ec593d9c2d5b716b1b86cfb0f37262ef34313a5a'
)
on conflict (case_id) do update set
