values (
  'ngoai-bung-003',
  '{"schema_version":"1.0.0","case_id":"ngoai-bung-003","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ngoai-bung-003-1","resource_type":"other","source":"HerniaSurge Group. International guidelines for groin hernia management. Hernia 2018.","title":"HerniaSurge Group. International guidelines for groin hernia management. Hernia 2018.","organization":null,"year_version":null,"citation":"HerniaSurge Group. International guidelines for groin hernia management. Hernia 2018.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-bung-003-2","resource_type":"textbook","source":"Giáo trình Bệnh học Ngoại khoa, Đại học Y Hà Nội, bài Thoát vị thành bụng.","title":"Giáo trình Bệnh học Ngoại khoa, Đại học Y Hà Nội, bài Thoát vị thành bụng.","organization":null,"year_version":null,"citation":"Giáo trình Bệnh học Ngoại khoa, Đại học Y Hà Nội, bài Thoát vị thành bụng.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-bung-003-3","resource_type":"textbook","source":"Townsend CM et al. Sabiston Textbook of Surgery, 21st edition, 2022, chương Abdominal Wall, Umbilicus, Hernia.","title":"Townsend CM et al. Sabiston Textbook of Surgery, 21st edition, 2022, chương Abdominal Wall, Umbilicus, Hernia.","organization":null,"year_version":null,"citation":"Townsend CM et al. Sabiston Textbook of Surgery, 21st edition, 2022, chương Abdominal Wall, Umbilicus, Hernia.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Tràn dịch màng tinh hoàn","credit":"none"},{"text":"Thoát vị bẹn gián tiếp bên phải bị nghẹt","credit":"full"},{"text":"Viêm mào tinh hoàn cấp","credit":"none"},{"text":"Xoắn thừng tinh","credit":"none"}]},"action_options":[{"text":"Nhịn ăn, đặt đường truyền, bù dịch tinh thể","time_minutes":2,"grade":"critical","rationale":"Nôn nhiều và mất nước, chuẩn bị mổ cấp cứu."},{"text":"Hội chẩn ngoại khoa và chuẩn bị mổ cấp cứu","time_minutes":2,"grade":"critical","rationale":"Nghẹt thoát vị cần can thiệp trong vài giờ để cứu ruột."},{"text":"Kháng sinh dự phòng trước mổ (cephalosporin), giảm đau tĩnh mạch","time_minutes":2,"grade":"critical","rationale":"Có dấu hiệu viêm, nguy cơ cắt ruột."},{"text":"Đặt sonde dạ dày hút khi nôn nhiều hoặc chướng bụng","time_minutes":2,"grade":"critical","rationale":"Giảm nguy cơ hít sặc khi gây mê."},{"text":"Đánh giá lại tim phổi, đường huyết và chuẩn bị gây mê","time_minutes":2,"grade":"recommended","rationale":"Người bệnh lớn tuổi hút thuốc, có tăng huyết áp."},{"text":"Đẩy khối tại chỗ vài lần trong khi chờ siêu âm","time_minutes":1,"grade":"waste","rationale":"Không an toàn khi nghi nghẹt và đã quá 6 giờ."},{"text":"Cố đẩy khối thoát vị bằng lực mạnh và cho về nhà","time_minutes":0,"grade":"harmful","rationale":"Đẩy ruột hoại tử vào ổ bụng gây viêm phúc mạc."}],"teaching_explanation":"Thoát vị bẹn không đẩy lên được kèm đau, nôn, bí trung đại tiện là nghẹt cho đến khi chứng minh ngược lại; cần mổ cấp cứu, không cố đẩy mạnh. Đánh giá sống ruột trong mổ quyết định cắt hay không cắt ruột."}'::jsonb,
