insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-bung-004',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-bung-004","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau hạ sườn phải, sốt sau bữa ăn nhiều mỡ","setting":"giuong","level":"Dễ","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":45,"sex":"nữ","patient_label":"Người bệnh mô phỏng T. T. M."},"presentation":{"intro":"Nữ 45 tuổi, thừa cân, đau hạ sườn phải liên tục 36 giờ sau bữa ăn nhiều mỡ, kèm sốt và buồn nôn.","place":null,"clock":null,"night":false},"vitals":{"hr":96,"sbp":125,"dbp":78,"rr":20,"temperature_c":38.3,"spo2":98},"history":[{"question":"Cơn đau khởi phát sau bữa ăn như thế nào?","response":"Sau bữa tiệc nhiều thịt mỡ, đau hạ sườn phải liên tục, tăng dần, kéo dài 36 giờ, lan lên vai phải."},{"question":"Có từng đau tương tự trước đây không?","response":"Vài lần đau quặn hạ sườn phải sau ăn mỡ, kéo dài dưới 2 giờ rồi tự hết."},{"question":"Có sốt, rét run hoặc vàng da không?","response":"Sốt 38 độ, không rét run, không vàng da, nước tiểu vàng, phân bình thường."},{"question":"Có buồn nôn, nôn không?","response":"Buồn nôn, nôn hai lần ra thức ăn, nôn xong đau không giảm."},{"question":"Đã dùng thuốc gì, có tiền sử sỏi mật hoặc bệnh gan không?","response":"Chưa từng siêu âm; tự uống thuốc giảm đau paracetamol; không bệnh gan."},{"question":"Có bệnh nền như đái tháo đường, tăng mỡ máu, dùng thuốc ngừa thai không?","response":"Rối loạn mỡ máu chưa điều trị; không đái tháo đường; sinh 3 con."},{"question":"Có dị ứng thuốc không?","response":"Không."}],"examination":[{"group":"K","item":"Khám bụng vùng hạ sườn phải","finding":"Ấn đau hạ sườn phải, dấu Murphy (+), co cứng nhẹ thành bụng hạ sườn phải."},{"group":"K","item":"Sờ túi mật và gan","finding":"Không sờ rõ túi mật; gan không to."},{"group":"K","item":"Toàn trạng, da niêm mạc","finding":"Tỉnh, thừa cân BMI 29, không vàng da, không vàng củng mạc, môi khô nhẹ."},{"group":"K","item":"Khám bụng toàn bộ","finding":"Bụng mềm vùng khác, không phản ứng dội lan tỏa, không chướng."},{"group":"K","item":"Tim phổi","finding":"Tim đều, phổi thông khí rõ."},{"group":"K","item":"Vùng thắt lưng","finding":"Chạm thận âm tính."}],"investigations":[{"name":"Công thức máu và CRP","duration_minutes":10,"result":"Bạch cầu 14,8 G/L; CRP 94 mg/L."},{"name":"Siêu âm bụng","duration_minutes":15,"result":"Túi mật căng 10 x 4,5 cm, thành dày 5 mm, có sỏi 1,5 cm kẹt ở cổ túi mật, dấu Murphy siêu âm (+), ít dịch quanh túi mật; ống mật chủ 5 mm; gan thoái hóa mỡ nhẹ."},{"name":"Chức năng gan: AST, ALT, bilirubin, ALP, GGT","duration_minutes":10,"result":"AST 52, ALT 48 U/L; bilirubin toàn phần 17 µmol/L; ALP và GGT trong giới hạn trên."},{"name":"Lipase và amylase máu","duration_minutes":10,"result":"Lipase 48 U/L (bình thường)."},{"name":"MRCP thường quy cho mọi người bệnh viêm túi mật","duration_minutes":40,"result":"Không cần khi ống mật chủ 5 mm, men gan gần bình thường."},{"name":"Chụp CT bụng có cản quang thường quy","duration_minutes":40,"result":"Không cần khi siêu âm đã đủ chẩn đoán, trừ nghi biến chứng."}],"choices":{"diagnosis":{"ydx":["Viêm tụy cấp do sỏi","Viêm đường mật cấp","Loét tá tràng thủng bít","Viêm túi mật cấp do sỏi, mức độ nhẹ (độ I theo Tokyo 2018)"]},"actions":["Đánh giá nguy cơ gây mê và điều chỉnh mỡ máu","Làm MRCP và ERCP ngay cho mọi người bệnh","Kháng sinh đường tĩnh mạch phổ phù hợp (ví dụ cephalosporin thế hệ 3 phối hợp metronidazol)","Hội chẩn ngoại khoa để lên kế hoạch cắt túi mật nội soi sớm","Nhịn ăn, truyền dịch và giảm đau","Theo dõi sinh hiệu, đau bụng và đánh giá lại mức độ nặng (lúc chẩn đoán, trong 24 giờ và lúc 24 đến 48 giờ); bilirubin, men gan theo diễn biến lâm sàng","Chỉ cho thuốc giảm co thắt rồi xuất viện"]}}'::jsonb,
  '9175df93735f4bca60cb6bb4af0c6766067ce297925b7a5d3fee6c412caa5cc5'
)
