insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'ngoai-bung-004',
  '{"schema_version":"1.0.0","case_id":"ngoai-bung-004","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-tg18-cholecystitis-flow","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/29045062/","title":"Miura F et al. Tokyo Guidelines 2018: flowchart for the management of acute cholecystitis. J Hepatobiliary Pancreat Sci 2018.","organization":null,"year_version":null,"citation":"Miura F et al. Tokyo Guidelines 2018: flowchart for the management of acute cholecystitis. J Hepatobiliary Pancreat Sci 2018.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-tg18-cholecystitis-dx","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/29032636/","title":"Yokoe M et al. Tokyo Guidelines 2018: diagnostic criteria and severity grading of acute cholecystitis. J Hepatobiliary Pancreat Sci 2018.","organization":null,"year_version":null,"citation":"Yokoe M et al. Tokyo Guidelines 2018: diagnostic criteria and severity grading of acute cholecystitis. J Hepatobiliary Pancreat Sci 2018.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-bung-004-3","resource_type":"textbook","source":"Giáo trình Bệnh học Ngoại khoa, Đại học Y Hà Nội, bài Sỏi mật và viêm túi mật.","title":"Giáo trình Bệnh học Ngoại khoa, Đại học Y Hà Nội, bài Sỏi mật và viêm túi mật.","organization":null,"year_version":null,"citation":"Giáo trình Bệnh học Ngoại khoa, Đại học Y Hà Nội, bài Sỏi mật và viêm túi mật.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,6],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"waste"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm tụy cấp do sỏi","credit":"none"},{"text":"Viêm đường mật cấp","credit":"none"},{"text":"Viêm túi mật cấp do sỏi, mức độ nhẹ (độ I theo Tokyo 2018)","credit":"full"},{"text":"Loét tá tràng thủng bít","credit":"none"}]},"action_options":[{"text":"Nhịn ăn, truyền dịch và giảm đau","time_minutes":2,"grade":"critical","rationale":"Giảm nôn, tránh mất nước, giảm đau không che dấu."},{"text":"Kháng sinh đường tĩnh mạch phổ phù hợp (ví dụ cephalosporin thế hệ 3 phối hợp metronidazol)","time_minutes":2,"grade":"critical","rationale":"Viêm túi mật có sốt và bạch cầu tăng; giảm nhiễm khuẩn huyết."},{"text":"Hội chẩn ngoại khoa để lên kế hoạch cắt túi mật nội soi sớm","time_minutes":2,"grade":"recommended","rationale":"Cắt sớm giảm thời gian nằm viện, giảm tái phát."},{"text":"Theo dõi sinh hiệu, đau bụng và đánh giá lại mức độ nặng (lúc chẩn đoán, trong 24 giờ và lúc 24 đến 48 giờ); bilirubin, men gan theo diễn biến lâm sàng","time_minutes":2,"grade":"recommended","rationale":"Phát hiện sớm biến chứng như thủng, viêm đường mật."},{"text":"Đánh giá nguy cơ gây mê và điều chỉnh mỡ máu","time_minutes":1,"grade":"recommended","rationale":"Chuẩn bị cho mổ nội soi."},{"text":"Chỉ cho thuốc giảm co thắt rồi xuất viện","time_minutes":0,"grade":"waste","rationale":"Không điều trị nguyên nhân, có nguy cơ biến chứng."},{"text":"Làm MRCP và ERCP ngay cho mọi người bệnh","time_minutes":0,"grade":"harmful","rationale":"Không có chỉ định, nguy cơ biến chứng thủ thuật."}],"teaching_explanation":"Đau hạ sườn phải kèm sốt, bạch cầu tăng, dấu Murphy dương và sỏi kẹt cổ túi mật trên siêu âm xác lập viêm túi mật cấp. Theo Tokyo 2018, độ I nên cắt túi mật nội soi sớm."}'::jsonb,
  '69286dcb3401b25f635bacca0f6a3876b92c97b51e10d3e9517583643a7a6ae1'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-bung-005',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-bung-005","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Sốt cao, vàng da, đau hạ sườn phải ở người đã cắt túi mật","setting":"capcuu","level":"Trung bình","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":68,"sex":"nam","patient_label":"Người bệnh mô phỏng L. V. D."},"presentation":{"intro":"Nam 68 tuổi đã cắt túi mật, nhập viện vì đau hạ sườn phải, sốt cao rét run và vàng da tăng dần trong 3 ngày.","place":null,"clock":null,"night":false},"vitals":{"hr":108,"sbp":98,"dbp":60,"rr":22,"temperature_c":39.4,"spo2":96},"history":[{"question":"Triệu chứng khởi phát và diễn tiến thế nào?","response":"Đau hạ sườn phải âm ỉ rồi tăng, sốt cao rét run 2 ngày, vàng da tăng dần từ hôm qua."},{"question":"Nước tiểu và phân thay đổi ra sao?","response":"Nước tiểu sẫm như nước trà, phân nhạt màu, ngứa nhẹ."},{"question":"Có tiền sử sỏi mật, mổ hoặc can thiệp đường mật không?","response":"Cắt túi mật mổ mở 6 năm trước vì sỏi túi mật; từng có sỏi ống mật chủ lấy qua ERCP 2 năm trước."},{"question":"Có mệt lả, lú lẫn, tiểu ít hoặc choáng váng không?","response":"Vẫn tỉnh táo nhưng mệt, tiểu ít từ sáng nay, chóng mặt khi đứng dậy."},{"question":"Có nôn, đau lan ra sau lưng hoặc đau thượng vị dữ dội không?","response":"Buồn nôn, không nôn, đau không lan ra lưng."},{"question":"Có bệnh nền, dùng thuốc chống đông hoặc kháng sinh gần đây không?","response":"Tăng huyết áp dùng enalapril; không dùng chống đông; không dùng kháng sinh gần đây."},{"question":"Có sụt cân, ăn kém kéo dài không?","response":"Không sụt cân rõ rệt trong 6 tháng."}],"examination":[{"group":"K","item":"Dấu hiệu sinh tồn và tưới máu","finding":"Mạch 108 lần/phút, huyết áp 98/60 mmHg, chi mát, thời gian đầy mao mạch 3 giây."},{"group":"K","item":"Da và củng mạc","finding":"Vàng da, vàng củng mạc rõ, vết gãi trầy xước nhẹ."},{"group":"K","item":"Khám bụng hạ sườn phải","finding":"Ấn đau hạ sườn phải, không co cứng lan tỏa; sẹo mổ cũ dưới sườn phải; gan không to, không sờ túi mật."},{"group":"K","item":"Tri giác","finding":"Tỉnh, trả lời đúng, GCS 15, mệt mỏi."},{"group":"K","item":"Tim phổi","finding":"Tim nhanh đều; phổi thông khí rõ."},{"group":"K","item":"Dấu hiệu xuất huyết","finding":"Không bầm máu, không xuất huyết dưới da."}],"investigations":[{"name":"Công thức máu, CRP, lactate, creatinin","duration_minutes":10,"result":"Bạch cầu 17,8 G/L; CRP 168 mg/L; lactate 3,2 mmol/L; creatinin 156 µmol/L; tiểu cầu 128 G/L."},{"name":"Chức năng gan mật và đông máu","duration_minutes":10,"result":"Bilirubin toàn phần 98 µmol/L, trực tiếp 74 µmol/L; AST 188, ALT 210 U/L; ALP và GGT tăng gấp 3 lần; INR 1,3."},{"name":"Cấy máu hai bộ trước kháng sinh","duration_minutes":10,"result":"Đã lấy hai bộ cấy; kết quả chờ."},{"name":"Siêu âm bụng","duration_minutes":15,"result":"Ống mật chủ giãn 13 mm, trong ống có sỏi khoảng 10 mm, gan trong và ngoài gan giãn nhẹ; không có túi mật."},{"name":"MRCP trước mọi quyết định dẫn lưu","duration_minutes":40,"result":"Không cần thiết và làm chậm giải áp khi đã đủ bằng chứng và người bệnh không ổn định."},{"name":"Nội soi dạ dày kiểm tra","duration_minutes":20,"result":"Không giúp xác định nguyên nhân, không có chỉ định."}],"choices":{"diagnosis":{"ydx":["Viêm gan virus cấp","Ung thư đầu tụy gây tắc mật","Viêm túi mật cấp","Viêm đường mật cấp do sỏi ống mật chủ, Tokyo độ II (trung bình), có đáp ứng viêm hệ thống"]},"actions":["Trì hoãn giải áp nhiều ngày để chờ bilirubin giảm","Hồi sức: oxy, truyền dịch tinh thể, theo dõi huyết áp và nước tiểu","Cấy máu rồi kháng sinh tĩnh mạch phổ rộng trong giờ đầu (ví dụ piperacillin-tazobactam)","Chỉ cho thuốc hạ sốt và theo dõi tại khoa","Vitamin K tĩnh mạch nếu INR kéo dài trước thủ thuật","Hội chẩn tiêu hóa can thiệp để giải áp đường mật bằng ERCP sớm","Đánh giá lại đáp ứng và suy cơ quan (lactate, creatinin, bilirubin) theo diễn biến lâm sàng; phân độ lại lúc chẩn đoán, trong 24 giờ và lúc 24 đến 48 giờ"]}}'::jsonb,
  'cd8abd8f2e3df0c8b1ee6faa36890ffc7ac36b5ce8bf533383ef4293d658748d'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'ngoai-bung-005',
  '{"schema_version":"1.0.0","case_id":"ngoai-bung-005","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-tg18-cholangitis-dx-ef32f039c76b","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/29032610/","title":"Kiriyama S et al. Tokyo Guidelines 2018: diagnostic criteria and severity grading of acute cholangitis. J Hepatobiliary Pancreat Sci 2018.","organization":null,"year_version":null,"citation":"Kiriyama S et al. Tokyo Guidelines 2018: diagnostic criteria and severity grading of acute cholangitis. J Hepatobiliary Pancreat Sci 2018.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-tg18-cholangitis-mgmt-fdc2d1f4ac6c","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/28941329/","title":"Miura F et al. Tokyo Guidelines 2018: initial management of acute biliary infection and flowchart for acute cholangitis. J Hepatobiliary Pancreat Sci 2018.","organization":null,"year_version":null,"citation":"Miura F et al. Tokyo Guidelines 2018: initial management of acute biliary infection and flowchart for acute cholangitis. J Hepatobiliary Pancreat Sci 2018.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-bung-005-3","resource_type":"other","source":"ESGE Clinical Guideline: Endoscopic management of common bile duct stones, 2019.","title":"ESGE Clinical Guideline: Endoscopic management of common bile duct stones, 2019.","organization":null,"year_version":null,"citation":"ESGE Clinical Guideline: Endoscopic management of common bile duct stones, 2019.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,5],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"waste"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm gan virus cấp","credit":"none"},{"text":"Viêm đường mật cấp do sỏi ống mật chủ, Tokyo độ II (trung bình), có đáp ứng viêm hệ thống","credit":"full"},{"text":"Viêm túi mật cấp","credit":"none"},{"text":"Ung thư đầu tụy gây tắc mật","credit":"none"}]},"action_options":[{"text":"Hồi sức: oxy, truyền dịch tinh thể, theo dõi huyết áp và nước tiểu","time_minutes":2,"grade":"critical","rationale":"Huyết áp 98/60, lactate 3,2, có dấu giảm tưới máu."},{"text":"Cấy máu rồi kháng sinh tĩnh mạch phổ rộng trong giờ đầu (ví dụ piperacillin-tazobactam)","time_minutes":2,"grade":"critical","rationale":"Viêm đường mật có đáp ứng viêm hệ thống cần kháng sinh sớm."},{"text":"Hội chẩn tiêu hóa can thiệp để giải áp đường mật bằng ERCP sớm","time_minutes":2,"grade":"critical","rationale":"Kiểm soát nguồn nhiễm là điều trị then chốt."},{"text":"Vitamin K tĩnh mạch nếu INR kéo dài trước thủ thuật","time_minutes":1,"grade":"critical","rationale":"Giảm nguy cơ chảy máu khi cắt cơ vòng."},{"text":"Đánh giá lại đáp ứng và suy cơ quan (lactate, creatinin, bilirubin) theo diễn biến lâm sàng; phân độ lại lúc chẩn đoán, trong 24 giờ và lúc 24 đến 48 giờ","time_minutes":2,"grade":"recommended","rationale":"Đánh giá đáp ứng và suy cơ quan."},{"text":"Chỉ cho thuốc hạ sốt và theo dõi tại khoa","time_minutes":0,"grade":"waste","rationale":"Không giải quyết tắc mật và nhiễm trùng."},{"text":"Trì hoãn giải áp nhiều ngày để chờ bilirubin giảm","time_minutes":0,"grade":"harmful","rationale":"Tắc mật nhiễm trùng không giải áp dễ tiến triển sốc nhiễm khuẩn."}],"teaching_explanation":"Bộ ba Charcot (đau hạ sườn phải, sốt rét run, vàng da) cộng với hình ảnh giãn ống mật có sỏi xác định viêm đường mật cấp. Kháng sinh sớm phải đi cùng giải áp đường mật; mức nặng Tokyo quyết định thời điểm và phương pháp."}'::jsonb,
  'a4871d57d659d09830b42c20de6656206cef90ec4878cfd1b2b4692b67c7d7f7'
)
