insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-bung-006',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-bung-006","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau bụng nhiều ngày rồi bụng cứng khắp bụng, sốt cao","setting":"capcuu","level":"Khó","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":71,"sex":"nam","patient_label":"Người bệnh mô phỏng P. V. K."},"presentation":{"intro":"Nam 71 tuổi đái tháo đường, đau bụng 4 ngày tự dùng thuốc giảm đau, hôm nay đau khắp bụng, sốt cao, mệt lả.","place":null,"clock":null,"night":false},"vitals":{"hr":118,"sbp":92,"dbp":55,"rr":26,"temperature_c":39,"spo2":94},"history":[{"question":"Đau bụng khởi phát và diễn tiến như thế nào?","response":"Bốn ngày trước đau quanh rốn rồi chuyển hố chậu phải; hôm qua đau giảm một lúc rồi nay đau dữ dội khắp bụng."},{"question":"Có sốt, nôn, bí trung đại tiện không?","response":"Sốt cao rét run từ đêm qua, nôn nhiều, không trung tiện từ sáng."},{"question":"Đã dùng thuốc gì trước khi nhập viện?","response":"Tự mua thuốc giảm đau paracetamol và kháng viêm, không dùng kháng sinh."},{"question":"Có bệnh nền nào, như đái tháo đường, bệnh tim, dùng corticoid không?","response":"Đái tháo đường type 2 mười năm, tăng huyết áp; không dùng corticoid."},{"question":"Có tiền sử mổ bụng hoặc loét dạ dày, viêm túi thừa không?","response":"Chưa mổ bụng, không loét dạ dày."},{"question":"Có đau lan lên vai, khó thở hoặc ho không?","response":"Hơi khó thở khi nằm, không ho."},{"question":"Có dị ứng thuốc không?","response":"Không dị ứng."}],"examination":[{"group":"K","item":"Dấu hiệu nhiễm khuẩn huyết và sốc","finding":"Mạch 118, huyết áp 92/55, nhịp thở 26, SpO2 94%, chi mát, mặt hốc hác, môi khô."},{"group":"K","item":"Khám bụng toàn bộ","finding":"Bụng chướng nhẹ, ít di động theo nhịp thở, co cứng thành bụng lan tỏa như gỗ, phản ứng dội (+) khắp bụng, ấn đau rõ hố chậu phải."},{"group":"K","item":"Gõ và nghe bụng","finding":"Gõ đục vùng thấp, mất vùng đục trước gan; nhu động ruột giảm."},{"group":"K","item":"Thăm trực tràng","finding":"Túi cùng Douglas căng đau, không có máu."},{"group":"K","item":"Tim phổi","finding":"Tim nhanh đều; phổi đáy phải ran ẩm nhẹ."},{"group":"K","item":"Dấu mất nước","finding":"Da nhăn, tiểu ít sẫm màu."}],"investigations":[{"name":"Công thức máu, CRP, procalcitonin, lactate, khí máu","duration_minutes":10,"result":"Bạch cầu 21,6 G/L, đa nhân trung tính 92%; CRP 286 mg/L; procalcitonin 8,4 ng/ml; lactate 4,1 mmol/L; pH 7,31."},{"name":"Điện giải, creatinin, đường huyết, đông máu","duration_minutes":10,"result":"Na 131, K 3,3 mmol/L; creatinin 164 µmol/L; đường huyết 16,8 mmol/L; INR 1,4."},{"name":"CT bụng chậu có cản quang","duration_minutes":40,"result":"Ruột thừa thủng, có sỏi phân ở hố chậu phải, ổ áp xe 4 x 3 cm quanh manh tràng, ít khí tự do ngoài lòng ruột, dịch ổ bụng lan tỏa, quai ruột non giãn nhẹ."},{"name":"X quang ngực bụng đứng","duration_minutes":10,"result":"Ít khí tự do dưới cơ hoành phải, đáy phổi phải mờ nhẹ."},{"name":"Nội soi đại tràng ngay để tìm nguyên nhân","duration_minutes":20,"result":"Chống chỉ định khi viêm phúc mạc, nguy cơ thủng."},{"name":"Chờ cấy máu có kết quả mới dùng kháng sinh","duration_minutes":10,"result":"Chậm kháng sinh trong nhiễm khuẩn huyết làm tăng tử vong."}],"choices":{"diagnosis":{"ydx":["Tắc ruột do dính sau mổ","Viêm dạ dày ruột cấp","Viêm phúc mạc toàn thể do ruột thừa vỡ, có nhiễm khuẩn huyết","Viêm tụy cấp hoại tử"]},"actions":["Hội chẩn ngoại khoa và gây mê hồi sức để mổ cấp cứu kiểm soát nguồn nhiễm","Hồi sức: 2 đường truyền, oxy, truyền dịch tinh thể 30 ml/kg, theo dõi huyết áp và nước tiểu","Kiểm soát đường huyết bằng insulin truyền","Đặt sonde dạ dày, sonde tiểu theo dõi nước tiểu","Làm nội soi đại tràng để tìm nguyên nhân khi bụng cứng","Cấy máu rồi kháng sinh tĩnh mạch phổ rộng trong giờ đầu (piperacillin-tazobactam hoặc carbapenem)","Cho thuốc giảm đau mạnh rồi quan sát 24 giờ"]}}'::jsonb,
  '5f6d6e1097feef7b60680726130a9a5315c60449c415b7f8c1c851a21fdf4efb'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'ngoai-bung-006',
  '{"schema_version":"1.0.0","case_id":"ngoai-bung-006","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-appendicitis-wses-2020-6bac2752e0aa","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/32295644/","title":"Di Saverio S et al. WSES Jerusalem guidelines for diagnosis and treatment of acute appendicitis, 2020.","organization":null,"year_version":null,"citation":"Di Saverio S et al. WSES Jerusalem guidelines for diagnosis and treatment of acute appendicitis, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-iai-wses-2017","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/28702076/","title":"Sartelli M et al. WSES/GAIS/SIS-E/WSIS/AAST global guidelines for intra-abdominal infections. World J Emerg Surg 2021.","organization":null,"year_version":null,"citation":"Sartelli M et al. WSES/GAIS/SIS-E/WSIS/AAST global guidelines for intra-abdominal infections. World J Emerg Surg 2021.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-sepsis-ssc-2021-dadd2d2cb325","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/34605781/","title":"Evans L et al. Surviving Sepsis Campaign: International Guidelines for Management of Sepsis and Septic Shock 2021.","organization":null,"year_version":null,"citation":"Evans L et al. Surviving Sepsis Campaign: International Guidelines for Management of Sepsis and Septic Shock 2021.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"waste"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Tắc ruột do dính sau mổ","credit":"none"},{"text":"Viêm phúc mạc toàn thể do ruột thừa vỡ, có nhiễm khuẩn huyết","credit":"full"},{"text":"Viêm tụy cấp hoại tử","credit":"none"},{"text":"Viêm dạ dày ruột cấp","credit":"none"}]},"action_options":[{"text":"Hồi sức: 2 đường truyền, oxy, truyền dịch tinh thể 30 ml/kg, theo dõi huyết áp và nước tiểu","time_minutes":2,"grade":"critical","rationale":"Huyết áp 92/55, lactate 4,1, có dấu giảm tưới máu."},{"text":"Cấy máu rồi kháng sinh tĩnh mạch phổ rộng trong giờ đầu (piperacillin-tazobactam hoặc carbapenem)","time_minutes":2,"grade":"critical","rationale":"Nhiễm khuẩn huyết do viêm phúc mạc cần kháng sinh sớm."},{"text":"Hội chẩn ngoại khoa và gây mê hồi sức để mổ cấp cứu kiểm soát nguồn nhiễm","time_minutes":2,"grade":"critical","rationale":"Viêm phúc mạc toàn thể cần mổ sớm sau hồi sức nhanh."},{"text":"Đặt sonde dạ dày, sonde tiểu theo dõi nước tiểu","time_minutes":2,"grade":"critical","rationale":"Giảm chướng, theo dõi tưới máu thận."},{"text":"Kiểm soát đường huyết bằng insulin truyền","time_minutes":2,"grade":"critical","rationale":"Đường huyết 16,8 làm nặng nhiễm trùng."},{"text":"Cho thuốc giảm đau mạnh rồi quan sát 24 giờ","time_minutes":0,"grade":"waste","rationale":"Làm chậm điều trị nguồn nhiễm."},{"text":"Làm nội soi đại tràng để tìm nguyên nhân khi bụng cứng","time_minutes":0,"grade":"harmful","rationale":"Nguy cơ thủng, chống chỉ định khi viêm phúc mạc."}],"teaching_explanation":"Đau bụng hố chậu phải nhiều ngày rồi co cứng khắp bụng kèm sốt cao, mạch nhanh, tụt huyết áp, lactate cao là viêm phúc mạc toàn thể do vỡ ruột thừa cho đến khi chứng minh ngược lại. Hồi sức nhanh, kháng sinh sớm và mổ kiểm soát nguồn nhiễm là ba trụ cột."}'::jsonb,
  '29ade187ee218f61a0930c1670d1fd6f317bbd7c613f06e1c5db7d92f2948374'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-bung-007',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-bung-007","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Thay đổi thói quen đi cầu nhiều tháng, nay bụng chướng và bí trung đại tiện","setting":"capcuu","level":"Khó","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":66,"sex":"nữ","patient_label":"Người bệnh mô phỏng Đ. T. H."},"presentation":{"intro":"Nữ 66 tuổi, 3 tháng nay đi cầu phân nhỏ lẫn máu, sụt cân, thiếu máu; 3 ngày nay bụng chướng to, nôn và không trung tiện.","place":null,"clock":null,"night":false},"vitals":{"hr":110,"sbp":100,"dbp":62,"rr":22,"temperature_c":37.6,"spo2":96},"history":[{"question":"Thói quen đại tiện thay đổi từ khi nào, như thế nào?","response":"Ba tháng nay táo bón xen kẽ tiêu chảy, phân nhỏ dẹt, thỉnh thoảng lẫn máu đỏ sẫm và nhầy."},{"question":"Có sụt cân, mệt, ăn kém không?","response":"Sụt 6 kg trong 3 tháng, mệt, da xanh, ăn kém."},{"question":"Ba ngày nay bụng thế nào?","response":"Bụng chướng to dần, đau quặn từng cơn vùng bụng dưới, nôn muộn ra dịch vàng, không trung tiện, không đi cầu 3 ngày."},{"question":"Có tiền sử polyp, bệnh viêm ruột hoặc ung thư trong gia đình không?","response":"Chưa nội soi đại tràng bao giờ; mẹ mất do ung thư đại tràng lúc 70 tuổi."},{"question":"Có tiền sử mổ bụng không?","response":"Chưa mổ bụng."},{"question":"Có bệnh nền và dùng thuốc gì không?","response":"Tăng huyết áp dùng amlodipin; không đái tháo đường; không dùng chống đông."},{"question":"Có sốt, đau bụng liên tục hoặc ngất không?","response":"Sốt nhẹ, không ngất, đau quặn từng cơn."}],"examination":[{"group":"K","item":"Khám bụng: nhìn, sờ, gõ","finding":"Bụng chướng căng không đều, nhìn thấy quai ruột nổi ở khung đại tràng, gõ vang, ấn đau nhẹ hố chậu trái, không co cứng."},{"group":"K","item":"Nghe nhu động ruột","finding":"Nhu động tăng, âm sắc cao, thỉnh thoảng có tiếng nước óc ách."},{"group":"K","item":"Thăm trực tràng","finding":"Bóng trực tràng rỗng, không sờ thấy khối thấp; găng dính ít phân nhầy lẫn máu."},{"group":"K","item":"Da niêm mạc và hạch","finding":"Da niêm mạc nhợt, môi khô; không hạch thượng đòn, không hạch bẹn."},{"group":"K","item":"Gan và dấu hiệu di căn","finding":"Gan không to, không dịch cổ trướng rõ."},{"group":"K","item":"Tim phổi","finding":"Tim nhanh đều; phổi trong."}],"investigations":[{"name":"Công thức máu, điện giải, creatinin, lactate","duration_minutes":10,"result":"Hồng cầu 3,2 T/L, Hb 82 g/L, MCV 72 fL; bạch cầu 11,4 G/L; Na 133, K 3,0 mmol/L; creatinin 112 µmol/L; lactate 2,0 mmol/L."},{"name":"X quang bụng đứng không chuẩn bị","duration_minutes":10,"result":"Đại tràng giãn khung, manh tràng 9,5 cm, ít hơi ở trực tràng, vài mức nước hơi ruột non."},{"name":"CT bụng chậu có cản quang","duration_minutes":40,"result":"Khối u dày thành đồng tâm đại tràng sigma dài khoảng 5 cm gây hẹp lòng; đại tràng phía trên giãn, manh tràng 9,5 cm; van hồi manh tràng đóng; không thủng, không khí tự do; vài hạch mạc treo 1 cm; một nốt gan 1,2 cm nghi di căn."},{"name":"CEA máu","duration_minutes":10,"result":"CEA 24 ng/ml (tăng)."},{"name":"Nội soi đại tràng ống cứng chuẩn bị bằng thuốc xổ ngay","duration_minutes":20,"result":"Chống chỉ định khi tắc ruột và nguy cơ thủng; không dùng thuốc xổ nhiều."},{"name":"Uống bari hoặc bơm thuốc cản quang bari đường hậu môn tùy tiện","duration_minutes":10,"result":"Nguy cơ thủng, không thay thế CT."}],"choices":{"diagnosis":{"ydx":["Tắc ruột do dính","Viêm túi thừa đại tràng sigma","Ung thư đại tràng sigma gây tắc ruột đại tràng kèm thiếu máu thiếu sắt","Xoắn đại tràng sigma"]},"actions":["Nội soi đại tràng ống cứng ngay khi đại tràng giãn căng","Kháng sinh dự phòng hoặc điều trị (ví dụ ceftriaxone phối hợp metronidazol)","Nhịn ăn, đặt sonde dạ dày hút, truyền dịch tinh thể","Bù kali, theo dõi điện giải, truyền hồng cầu khi cần","Đánh dấu vị trí hậu môn nhân tạo, giải thích người bệnh và gia đình","Thụt tháo bằng nước nhiều lần","Hội chẩn ngoại, nội soi tiêu hóa can thiệp và gây mê hồi sức"]}}'::jsonb,
  '18ff66e231172c2086371471e8699db01d13364fe3a43885a290731363727d52'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
