values (
  'ngoai-bung-007',
  '{"schema_version":"1.0.0","case_id":"ngoai-bung-007","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-crc-wses-2018","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/30123315/","title":"Pisano M et al. 2017 WSES guidelines on colon and rectal cancer emergencies: obstruction and perforation. World J Emerg Surg 2018.","organization":null,"year_version":null,"citation":"Pisano M et al. 2017 WSES guidelines on colon and rectal cancer emergencies: obstruction and perforation. World J Emerg Surg 2018.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-bung-007-2","resource_type":"other","source":"van Hooft JE et al. Self-expandable metal stents for obstructing colonic and extracolonic cancer: ESGE Clinical Guideline update. Endoscopy 2020.","title":"van Hooft JE et al. Self-expandable metal stents for obstructing colonic and extracolonic cancer: ESGE Clinical Guideline update. Endoscopy 2020.","organization":null,"year_version":null,"citation":"van Hooft JE et al. Self-expandable metal stents for obstructing colonic and extracolonic cancer: ESGE Clinical Guideline update. Endoscopy 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-bung-007-3","resource_type":"other","source":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị ung thư đại trực tràng, Quyết định hiện hành.","title":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị ung thư đại trực tràng, Quyết định hiện hành.","organization":null,"year_version":null,"citation":"Bộ Y tế. Hướng dẫn chẩn đoán và điều trị ung thư đại trực tràng, Quyết định hiện hành.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Tắc ruột do dính","credit":"none"},{"text":"Xoắn đại tràng sigma","credit":"none"},{"text":"Viêm túi thừa đại tràng sigma","credit":"none"},{"text":"Ung thư đại tràng sigma gây tắc ruột đại tràng kèm thiếu máu thiếu sắt","credit":"full"}]},"action_options":[{"text":"Nhịn ăn, đặt sonde dạ dày hút, truyền dịch tinh thể","time_minutes":2,"grade":"critical","rationale":"Giảm chướng, bù dịch cho người bệnh mất nước và hạ natri."},{"text":"Bù kali, theo dõi điện giải, truyền hồng cầu khi cần","time_minutes":2,"grade":"critical","rationale":"K 3,0 mmol/L và Hb 82 g/L cần điều chỉnh trước mổ."},{"text":"Kháng sinh dự phòng hoặc điều trị (ví dụ ceftriaxone phối hợp metronidazol)","time_minutes":2,"grade":"critical","rationale":"Giảm nguy cơ nhiễm khuẩn, tiên lượng thủng."},{"text":"Hội chẩn ngoại, nội soi tiêu hóa can thiệp và gây mê hồi sức","time_minutes":2,"grade":"critical","rationale":"Quyết định mổ cấp cứu hay đặt stent làm cầu nối."},{"text":"Đánh dấu vị trí hậu môn nhân tạo, giải thích người bệnh và gia đình","time_minutes":2,"grade":"recommended","rationale":"Chuẩn bị tâm lý, cho khả năng cắt Hartmann."},{"text":"Thụt tháo bằng nước nhiều lần","time_minutes":0,"grade":"waste","rationale":"Có thể gây thủng, không giải quyết tắc nghẽn cơ học."},{"text":"Nội soi đại tràng ống cứng ngay khi đại tràng giãn căng","time_minutes":0,"grade":"harmful","rationale":"Nguy cơ thủng đại tràng, không có chỉ định cấp cứu."}],"teaching_explanation":"Thay đổi thói quen đại tiện, phân máu, sụt cân, thiếu máu thiếu sắt ở người trên 50 tuổi là báo động ung thư đại trực tràng. Khi tắc ruột đại tràng, manh tràng giãn quá 10 đến 12 cm kèm van hồi manh tràng đóng cần xử trí khẩn để tránh thủng."}'::jsonb,
  '6a0483c173563401be3f218f319966e9b74982643e171a8fd56c006dd6cc4881'
)
