insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-bung-008',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-bung-008","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau nhức nhối cạnh hậu môn, sưng nóng đỏ và sốt","setting":"giuong","level":"Dễ","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":34,"sex":"nam","patient_label":"Người bệnh mô phỏng V. M. Q."},"presentation":{"intro":"Nam 34 tuổi đến khám vì đau nhức nhối vùng hậu môn bên trái 4 ngày, có cục sưng nóng đỏ, ngồi đau và sốt.","place":null,"clock":null,"night":false},"vitals":{"hr":94,"sbp":122,"dbp":76,"rr":18,"temperature_c":38.4,"spo2":99},"history":[{"question":"Đau và sưng cạnh hậu môn khởi phát thế nào?","response":"Bốn ngày nay đau nhức nhối, tăng dần, có cục sưng nóng đỏ cạnh hậu môn bên trái, ngồi hoặc đi lại đau nhiều, đau cả đêm."},{"question":"Có sốt, rét run không?","response":"Sốt khoảng 38 độ và ớn lạnh từ hôm qua."},{"question":"Có chảy mủ, chảy dịch hoặc đại tiện đau không?","response":"Chưa có mủ chảy ra; đại tiện đau nhiều, hơi táo bón vài ngày."},{"question":"Có tiền sử áp xe hoặc rò hậu môn, bệnh viêm ruột không?","response":"Cách đây 2 năm có một lần sưng đau tương tự, tự giảm sau uống kháng sinh."},{"question":"Có đái tháo đường, suy giảm miễn dịch hoặc dùng corticoid không?","response":"Không bệnh nền, không dùng corticoid."},{"question":"Có quan hệ tình dục hậu môn hoặc chấn thương vùng hậu môn không?","response":"Không chấn thương; không quan hệ qua hậu môn."},{"question":"Có tiểu khó, tiểu buốt hay sút cân không?","response":"Không."}],"examination":[{"group":"K","item":"Nhìn vùng quanh hậu môn","finding":"Khối sưng nóng đỏ cạnh hậu môn vị trí 9 giờ (tư thế sản khoa), đường kính khoảng 4 cm, cách bờ hậu môn khoảng 2 cm, da căng bóng."},{"group":"K","item":"Sờ khối","finding":"Rất đau, căng, nóng, có dấu bập bềnh (+), không có bờ hậu môn bị tụt xuống."},{"group":"K","item":"Thăm trực tràng","finding":"Đau nhiều, khó thăm; sờ thấy vùng căng cứng thành bên trái ống hậu môn; không khối trực tràng."},{"group":"K","item":"Toàn trạng","finding":"Tỉnh, vẻ mặt đau, nhiệt độ 38,4 độ C, không dấu hiệu nhiễm khuẩn huyết."},{"group":"K","item":"Khám bụng","finding":"Bụng mềm, không đau."},{"group":"K","item":"Hạch bẹn","finding":"Không hạch bẹn to."}],"investigations":[{"name":"Công thức máu và CRP","duration_minutes":10,"result":"Bạch cầu 14,6 G/L; CRP 54 mg/L."},{"name":"Đường huyết lúc đói","duration_minutes":10,"result":"Đường huyết 5,6 mmol/L."},{"name":"Siêu âm phần mềm hoặc siêu âm nội trực tràng","duration_minutes":15,"result":"Ổ tụ dịch 3,8 x 2,6 cm dưới da cạnh hậu môn bên trái, có vách mỏng, chưa thấy lỗ dò rõ."},{"name":"MRI vùng chậu","duration_minutes":10,"result":"Chỉ định khi áp xe phức tạp, tái phát hoặc nghi dò phức tạp, không cần ở ca đơn giản này."},{"name":"Chụp CT bụng chậu thường quy cho mọi người bệnh","duration_minutes":40,"result":"Không cần ở ca áp xe quanh hậu môn đơn giản, tăng chi phí và bức xạ."},{"name":"Chỉ cho kháng sinh uống và chờ áp xe tự vỡ","duration_minutes":10,"result":"Không đủ, áp xe mủ cần dẫn lưu."}],"choices":{"diagnosis":{"ydx":["Trĩ ngoại tắc mạch","Nang lông vùng cụt bị viêm","Áp xe quanh hậu môn dưới da bên trái","Nứt kẽ hậu môn cấp"]},"actions":["Giảm đau (paracetamol, NSAID), nhuận tràng mềm phân","Chọc hút mủ nhiều lần rồi đóng kín vết rạch","Rạch dẫn lưu mủ tại chỗ hoặc trong phòng mổ dưới gây tê, rạch gần bờ hậu môn","Chỉ chườm ấm và uống kháng sinh","Ngâm ngồi nước ấm 2 đến 3 lần mỗi ngày sau dẫn lưu, thay băng","Giải thích thủ thuật, ký cam kết và chuẩn bị rạch dẫn lưu","Gửi dịch mủ nuôi cấy khi có yếu tố nguy cơ, đái tháo đường hoặc tái phát"]}}'::jsonb,
  '4d3e0e5674c3bd4b5beefce66e64e05d8f7a149fa2c47dec3f7fc3b05d487830'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'ngoai-bung-008',
  '{"schema_version":"1.0.0","case_id":"ngoai-bung-008","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-anorectal-abscess-ascrs-2022","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/35732009/","title":"Gaertner WB et al. The American Society of Colon and Rectal Surgeons Clinical Practice Guidelines for the Management of Anorectal Abscess, Fistula-in-Ano, and Rectovaginal Fistula. Dis Colon Rectum 2022.","organization":null,"year_version":null,"citation":"Gaertner WB et al. The American Society of Colon and Rectal Surgeons Clinical Practice Guidelines for the Management of Anorectal Abscess, Fistula-in-Ano, and Rectovaginal Fistula. Dis Colon Rectum 2022.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-bung-008-2","resource_type":"textbook","source":"Giáo trình Bệnh học Ngoại khoa, Đại học Y Hà Nội, bài Áp xe hậu môn và rò hậu môn.","title":"Giáo trình Bệnh học Ngoại khoa, Đại học Y Hà Nội, bài Áp xe hậu môn và rò hậu môn.","organization":null,"year_version":null,"citation":"Giáo trình Bệnh học Ngoại khoa, Đại học Y Hà Nội, bài Áp xe hậu môn và rò hậu môn.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-bung-008-3","resource_type":"textbook","source":"Townsend CM et al. Sabiston Textbook of Surgery, 21st edition, 2022, chương Anus.","title":"Townsend CM et al. Sabiston Textbook of Surgery, 21st edition, 2022, chương Anus.","organization":null,"year_version":null,"citation":"Townsend CM et al. Sabiston Textbook of Surgery, 21st edition, 2022, chương Anus.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Trĩ ngoại tắc mạch","credit":"none"},{"text":"Nứt kẽ hậu môn cấp","credit":"none"},{"text":"Nang lông vùng cụt bị viêm","credit":"none"},{"text":"Áp xe quanh hậu môn dưới da bên trái","credit":"full"}]},"action_options":[{"text":"Giải thích thủ thuật, ký cam kết và chuẩn bị rạch dẫn lưu","time_minutes":2,"grade":"critical","rationale":"Áp xe có mủ cần dẫn lưu, kháng sinh đơn thuần không đủ."},{"text":"Rạch dẫn lưu mủ tại chỗ hoặc trong phòng mổ dưới gây tê, rạch gần bờ hậu môn","time_minutes":2,"grade":"critical","rationale":"Dẫn lưu sớm giảm đau, giảm lan rộng; rạch gần bờ hậu môn giảm đường dò dài."},{"text":"Giảm đau (paracetamol, NSAID), nhuận tràng mềm phân","time_minutes":2,"grade":"recommended","rationale":"Giảm đau khi đại tiện và hạn chế táo bón."},{"text":"Ngâm ngồi nước ấm 2 đến 3 lần mỗi ngày sau dẫn lưu, thay băng","time_minutes":2,"grade":"recommended","rationale":"Giúp vết thương dẫn lưu liền từ đáy."},{"text":"Gửi dịch mủ nuôi cấy khi có yếu tố nguy cơ, đái tháo đường hoặc tái phát","time_minutes":1,"grade":"recommended","rationale":"Chọn kháng sinh theo vi khuẩn khi cần."},{"text":"Chỉ chườm ấm và uống kháng sinh","time_minutes":0,"grade":"waste","rationale":"Không dẫn lưu mủ, bệnh kéo dài và dễ lan."},{"text":"Chọc hút mủ nhiều lần rồi đóng kín vết rạch","time_minutes":0,"grade":"harmful","rationale":"Áp xe tái phát nhanh, tăng nguy cơ dò và nhiễm trùng lan."}],"teaching_explanation":"Đau nhức nhối cạnh hậu môn kèm khối sưng nóng đỏ, dấu bập bềnh là áp xe quanh hậu môn; điều trị cơ bản là rạch dẫn lưu mủ. Khoảng 30 đến 50% có dò hậu môn về sau nên cần hẹn tái khám."}'::jsonb,
  'a296919679a59d8dcf412805d2802b4c9e397c2f93e808b2bab33b0d14b4f268'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngoai-chan-thuong-001',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngoai-chan-thuong-001","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Ngã xe máy, tỉnh rồi li bì, đồng tử phải giãn","setting":"capcuu","level":"Khó","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":24,"sex":"nam","patient_label":"Anh Q. M. T."},"presentation":{"intro":"Nam thanh niên được đưa vào phòng cấp cứu sau ngã xe máy không đội mũ bảo hiểm khoảng 3 giờ, ban đầu tỉnh táo nhưng nay li bì dần, nôn và đau đầu tăng.","place":null,"clock":null,"night":false},"vitals":{"hr":56,"sbp":164,"dbp":92,"rr":14,"temperature_c":36.8,"spo2":96},"history":[{"question":"Tai nạn xảy ra thế nào, anh có bị đập đầu không?","response":"Ngã xe máy cách đây khoảng 3 giờ, không đội mũ bảo hiểm, đập đầu bên phải xuống mặt đường."},{"question":"Sau tai nạn có mất ý thức không, có tỉnh lại rồi mới li bì không?","response":"Choáng vài phút rồi tỉnh, nói chuyện được khoảng một giờ; sau đó đau đầu tăng, nôn và li bì dần (người nhà kể)."},{"question":"Có nôn, co giật, chảy máu hoặc dịch qua tai, mũi không?","response":"Nôn vọt hai lần; chảy ít máu từ tai phải; chưa co giật."},{"question":"Có dùng rượu hoặc thuốc chống đông, chống kết tập tiểu cầu không?","response":"Uống ít bia trước khi đi xe; không dùng thuốc chống đông."},{"question":"Có đau cổ, đau ngực, đau bụng hoặc yếu tay chân không?","response":"Đau cổ nhẹ; tay chân trái yếu hơn bên phải; ngực bụng không than đau."},{"question":"Tiền sử bệnh, dị ứng, tiêm phòng uốn ván?","response":"Khỏe mạnh, không dị ứng; chưa nhớ đã tiêm phòng uốn ván."},{"question":"Bữa ăn gần nhất cách đây bao lâu?","response":"Bữa trưa, cách đây khoảng 4 giờ."}],"examination":[{"group":"K","item":"Đánh giá ABCDE và điểm Glasgow","finding":"Đường thở thông nhưng nguy cơ tắc khi nôn; Glasgow 11 điểm (E3 V3 M5), giảm từ 14 điểm lúc ở hiện trường."},{"group":"K","item":"Đồng tử và dấu thần kinh khu trú","finding":"Đồng tử phải 5 mm, phản xạ ánh sáng chậm; trái 3 mm, phản xạ tốt. Yếu nửa người trái, sức cơ 3/5."},{"group":"K","item":"Da đầu và nền sọ","finding":"Tụ máu dưới da thái dương phải, vết rách da đầu 4 cm đã cầm máu; máu khô ở ống tai ngoài phải; chưa thấy mắt gấu."},{"group":"K","item":"Cột sống cổ","finding":"Đau nhẹ vùng cổ, chưa có dấu thần kinh tủy; đang cố định bằng nẹp cổ."},{"group":"K","item":"Ngực, bụng, khung chậu và các chi","finding":"Không thấy dấu tổn thương ngực bụng; khung chậu vững; chi không biến dạng."}],"investigations":[{"name":"Đường huyết mao mạch","duration_minutes":10,"result":"6,2 mmol/L."},{"name":"CT sọ não không cản quang (có cửa sổ xương)","duration_minutes":40,"result":"Tụ máu ngoài màng cứng thái dương đỉnh phải hình thấu kính, dày tối đa 24 mm, thể tích ước tính khoảng 47 mL; đường giữa lệch sang trái 8 mm; nứt xương thái dương phải qua rãnh động mạch màng não giữa."},{"name":"Công thức máu, nhóm máu, đông máu toàn bộ","duration_minutes":10,"result":"Hb 14,1 g/dL; tiểu cầu 238 G/L; INR 1,0; đã có nhóm máu và chuẩn bị máu."},{"name":"CT cột sống cổ (cùng đợt chụp sọ não)","duration_minutes":40,"result":"Không thấy gãy hay trật."},{"name":"Điện giải đồ, chức năng thận","duration_minutes":10,"result":"Na 138 mmol/L, K 3,9 mmol/L, creatinin bình thường."},{"name":"MRI sọ não trước khi quyết định mổ","duration_minutes":10,"result":"Không cần thiết, làm chậm phẫu thuật cấp cứu khi CT đã chẩn đoán rõ."}],"choices":{"diagnosis":{"ydx":["Chấn thương sọ não nhẹ, có thể theo dõi tại nhà","Tụ máu ngoài màng cứng thái dương đỉnh phải do tổn thương động mạch màng não giữa, có dấu thoát vị thái dương","Tụ máu dưới màng cứng cấp do rách tĩnh mạch cầu nối","Xuất huyết dưới nhện tự phát do vỡ phình mạch"]},"actions":["Dùng dung dịch ưu trương (Manitol hoặc NaCl 3%) như cầu nối khi có dấu thoát vị","Mở sọ lấy máu tụ ngoài màng cứng cấp cứu","Sau mổ theo dõi hồi sức, CT kiểm tra, dự phòng co giật sớm, chăm sóc vết thương, phòng uốn ván","Cho nằm quan sát vài giờ ở khoa thường rồi chụp lại CT","Chụp CT sọ não khẩn ngay khi ổn định ban đầu và gọi phẫu thuật thần kinh","Chọc dò dịch não tủy thắt lưng để khẳng định chẩn đoán","Đánh giá ABCDE, cố định cổ, thở oxy, nâng đầu 30 độ","Đặt hai đường truyền, lấy máu, đặt thông tiểu, theo dõi tri giác và đồng tử thường xuyên (tối thiểu mỗi giờ, dày hơn khi diễn biến xấu)"]}}'::jsonb,
  '74ce63e0fdef12cf5fd9c6e307ae7d05aaea6d32e00c419623f6de660cd46cd3'
)
on conflict (case_id) do update set
