  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'ngoai-chan-thuong-001',
  '{"schema_version":"1.0.0","case_id":"ngoai-chan-thuong-001","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-001-1","resource_type":"other","source":"ATLS 10th edition, American College of Surgeons, 2018: chương Chấn thương đầu.","title":"ATLS 10th edition, American College of Surgeons, 2018: chương Chấn thương đầu.","organization":null,"year_version":null,"citation":"ATLS 10th edition, American College of Surgeons, 2018: chương Chấn thương đầu.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-tbi-btf-2017-372ee4b43c67","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/27654000/","title":"Brain Trauma Foundation: Guidelines for the Management of Severe Traumatic Brain Injury, 4th edition, 2016; Surgical Management of Acute Epidural Hematomas, 2006.","organization":null,"year_version":null,"citation":"Brain Trauma Foundation: Guidelines for the Management of Severe Traumatic Brain Injury, 4th edition, 2016; Surgical Management of Acute Epidural Hematomas, 2006.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ngoai-chan-thuong-001-3","resource_type":"textbook","source":"Giáo trình Ngoại bệnh lý (Đại học Y Hà Nội và Đại học Y Dược TP.HCM): bài Chấn thương sọ não.","title":"Giáo trình Ngoại bệnh lý (Đại học Y Hà Nội và Đại học Y Dược TP.HCM): bài Chấn thương sọ não.","organization":null,"year_version":null,"citation":"Giáo trình Ngoại bệnh lý (Đại học Y Hà Nội và Đại học Y Dược TP.HCM): bài Chấn thương sọ não.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Tụ máu dưới màng cứng cấp do rách tĩnh mạch cầu nối","credit":"none"},{"text":"Tụ máu ngoài màng cứng thái dương đỉnh phải do tổn thương động mạch màng não giữa, có dấu thoát vị thái dương","credit":"full"},{"text":"Chấn thương sọ não nhẹ, có thể theo dõi tại nhà","credit":"none"},{"text":"Xuất huyết dưới nhện tự phát do vỡ phình mạch","credit":"none"}]},"action_options":[{"text":"Đánh giá ABCDE, cố định cổ, thở oxy, nâng đầu 30 độ","time_minutes":2,"grade":"critical","rationale":"Ưu tiên đường thở và oxy; thiếu oxy và hạ huyết áp gây tổn thương não thứ phát."},{"text":"Chụp CT sọ não khẩn ngay khi ổn định ban đầu và gọi phẫu thuật thần kinh","time_minutes":2,"grade":"critical","rationale":"Tri giác giảm, đồng tử không đều gợi ý thoát vị; CT xác định chẩn đoán và chỉ định mổ."},{"text":"Đặt hai đường truyền, lấy máu, đặt thông tiểu, theo dõi tri giác và đồng tử thường xuyên (tối thiểu mỗi giờ, dày hơn khi diễn biến xấu)","time_minutes":2,"grade":"critical","rationale":"Theo dõi sát giúp phát hiện sớm diễn tiến xấu và chuẩn bị mổ."},{"text":"Dùng dung dịch ưu trương (Manitol hoặc NaCl 3%) như cầu nối khi có dấu thoát vị","time_minutes":2,"grade":"critical","rationale":"Giảm tạm thời áp lực nội sọ trong lúc chuẩn bị mổ, không thay thế phẫu thuật."},{"text":"Mở sọ lấy máu tụ ngoài màng cứng cấp cứu","time_minutes":3,"grade":"recommended","rationale":"Thể tích trên 30 mL là chỉ định mổ bất kể Glasgow; ở đây còn có đồng tử bất thường và lệch đường giữa."},{"text":"Sau mổ theo dõi hồi sức, CT kiểm tra, dự phòng co giật sớm, chăm sóc vết thương, phòng uốn ván","time_minutes":2,"grade":"recommended","rationale":"Đề phòng chảy máu tái phát, phù não và biến chứng thứ phát."},{"text":"Chọc dò dịch não tủy thắt lưng để khẳng định chẩn đoán","time_minutes":0,"grade":"harmful","rationale":"Khi áp lực nội sọ tăng có thể gây tụt kẹt hạnh nhân tiểu não."},{"text":"Cho nằm quan sát vài giờ ở khoa thường rồi chụp lại CT","time_minutes":0,"grade":"harmful","rationale":"Đã có dấu thoát vị; chậm trễ làm tăng tử vong và di chứng."}],"teaching_explanation":"Khoảng tỉnh rồi li bì, đồng tử giãn cùng bên tụ máu, mạch chậm huyết áp cao và nứt xương thái dương là bộ khung của tụ máu ngoài màng cứng. Đây là cấp cứu ngoại thần kinh: bảo vệ đường thở, CT khẩn và mổ sớm quyết định tiên lượng."}'::jsonb,
  '69916d3cb2e4833fcba7821adce70b06661a8515243208c3f0704579940a5f03'
)
